  1→// ─── Shared List Navigation Styles ────────────────────────────────────────────
  2→.nav-list {
  3→    flex: 1;
  4→    overflow-y: auto;
  5→    padding: 0 8px 12px;
  6→    display: flex;
  7→    flex-direction: column;
  8→    gap: 2px;
  9→}
 10→
 11→.nav-item {
 12→    position: relative;
 13→    width: 100%;
 14→    display: flex;
 15→    align-items: center;
 16→    gap: 10px;
 17→    padding: 6px 4px;
 18→    border: 1px solid transparent;
 19→    border-radius: 10px;
 20→    background: transparent;
 21→    color: var(--mat-sys-on-surface-variant);
 22→    text-align: left;
 23→    text-decoration: none;
 24→    cursor: pointer;
 25→    font-size: 0.875rem;
 26→    font-weight: 500;
 27→    box-sizing: border-box;
 28→    transition:
 29→        background 0.15s ease,
 30→        color 0.15s ease,
 31→        border-color 0.15s ease,
 32→        box-shadow 0.18s ease,
 33→        transform 0.18s ease;
 34→
 35→    mat-icon {
 36→        font-size: 18px;
 37→        width: 18px;
 38→        height: 18px;
 39→        flex-shrink: 0;
 40→    }
 41→
 42→    span,
 43→    .nav-item-label {
 44→        line-height: 1.2;
 45→        white-space: nowrap;
 46→        overflow: hidden;
 47→        text-overflow: ellipsis;
 48→        flex: 1;
 49→        min-width: 0;
 50→        padding-left: 10px;
 51→    }
 52→
 53→    .nav-item-meta {
 54→        font-size: 0.8rem;
 55→        min-width: 2ch;
 56→        text-align: right;
 57→        flex-shrink: 0;
 58→        color: var(--mat-sys-on-surface-variant);
 59→        opacity: 0.7;
 60→    }
 61→
 62→    &:hover:not(.selected):not(.active):not(.is-active) {
 63→        background: var(--app-selection-surface);
 64→        color: var(--mat-sys-on-surface);
 65→    }
 66→
 67→    &.selected,
 68→    &.active,
 69→    &.is-active {
 70→        background: linear-gradient(
 71→            135deg,
 72→            var(--app-selection-surface-strong),
 73→            var(--app-selection-surface)
 74→        ) !important;
 75→        color: var(--app-selection-color) !important;
 76→        border-color: var(--app-selection-border) !important;
 77→        font-weight: 600;
 78→        box-shadow:
 79→            inset 0 0 0 1px var(--app-selection-border),
 80→            0 12px 20px -18px var(--app-selection-glow);
 81→        transform: translateY(-1px);
 82→
 83→        * {
 84→            color: var(--app-selection-color) !important;
 85→        }
 86→
 87→        .nav-item-meta {
 88→            color: var(--app-selection-color) !important;
 89→            opacity: 0.92;
 90→        }
 91→
 92→        /* &::before {
 93→            content: '';
 94→            position: absolute;
 95→            inset-inline-start: 2px;
 96→            top: 7px;
 97→            bottom: 7px;
 98→            width: 2px;
 99→            border-radius: 999px;
100→            background: var(--app-selection-color);
101→            box-shadow: 0 0 10px var(--app-selection-glow);
102→        } */
103→    }
104→}
105→

 1→// ─── IPTVnator UI styles library ─────────────────────────────────────────────
 2→// Add libs/ui/styles to stylePreprocessorOptions.includePaths in project.json
 3→// to import these without relative paths:
 4→//
 5→//   @use 'portal-layout'  as portal;
 6→//   @use 'content-grid'   as grid;
 7→//   @use 'portal-sidebar';
 8→
 9→@forward 'portal-layout';
10→@forward 'content-grid';
11→@forward 'portal-sidebar';
12→

  1→// Shared content grid and card styles
  2→//
  3→// Usage (after adding libs/ui/styles to stylePreprocessorOptions.includePaths):
  4→//   @use 'content-grid' as grid;
  5→//   @include grid.content-grid;
  6→//   @include grid.content-card;
  7→
  8→@mixin content-grid($min-width: 140px, $gap: 20px) {
  9→    display: grid;
 10→    grid-template-columns: repeat(auto-fill, minmax($min-width, 1fr));
 11→    gap: $gap;
 12→}
 13→
 14→@mixin content-card {
 15→    cursor: pointer;
 16→    border-radius: 8px;
 17→    overflow: hidden;
 18→    transition: transform 0.2s ease, box-shadow 0.2s ease;
 19→
 20→    &:hover {
 21→        transform: translateY(-3px);
 22→        box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
 23→    }
 24→}
 25→
 26→@mixin thumbnail-wrapper {
 27→    position: relative;
 28→    border-radius: 8px;
 29→    overflow: hidden;
 30→
 31→    .poster {
 32→        width: 100%;
 33→        aspect-ratio: 2/3;
 34→        object-fit: cover;
 35→        display: block;
 36→    }
 37→
 38→    .poster-placeholder {
 39→        width: 100%;
 40→        aspect-ratio: 2/3;
 41→        display: flex;
 42→        align-items: center;
 43→        justify-content: center;
 44→        background: rgba(128, 128, 128, 0.1);
 45→
 46→        mat-icon {
 47→            font-size: 36px;
 48→            width: 36px;
 49→            height: 36px;
 50→            opacity: 0.25;
 51→        }
 52→    }
 53→}
 54→
 55→@mixin type-badge {
 56→    position: absolute;
 57→    top: 6px;
 58→    left: 6px;
 59→    padding: 3px 6px;
 60→    border-radius: 4px;
 61→    font-size: 9px;
 62→    font-weight: 700;
 63→    text-transform: uppercase;
 64→    letter-spacing: 0.5px;
 65→    background: rgba(0, 0, 0, 0.85);
 66→    color: #fff;
 67→
 68→    &.live {
 69→        color: #ef5350;
 70→    }
 71→    &.movie {
 72→        color: #42a5f5;
 73→    }
 74→    &.series {
 75→        color: #66bb6a;
 76→    }
 77→}
 78→
 79→@mixin remove-button {
 80→    position: absolute;
 81→    top: 4px;
 82→    right: 4px;
 83→    z-index: 1;
 84→    background: rgba(0, 0, 0, 0.5);
 85→    width: 28px;
 86→    height: 28px;
 87→    padding: 0;
 88→
 89→    &:hover {
 90→        background: rgba(0, 0, 0, 0.8);
 91→    }
 92→
 93→    mat-icon {
 94→        color: white;
 95→        font-size: 18px;
 96→        width: 18px;
 97→        height: 18px;
 98→    }
 99→}
100→
101→@mixin card-info {
102→    padding: 8px 10px;
103→
104→    h3 {
105→        margin: 0;
106→        font-size: 0.8rem;
107→        font-weight: 500;
108→        line-height: 1.3;
109→        display: -webkit-box;
110→        -webkit-line-clamp: 2;
111→        -webkit-box-orient: vertical;
112→        overflow: hidden;
113→    }
114→
115→    .date-info {
116→        margin: 4px 0 0;
117→        font-size: 0.7rem;
118→        opacity: 0.6;
119→    }
120→}
121→

 1→// ─── Shared mixin for live-stream portal layouts ──────────────────────────────
 2→// Used by: xtream live-stream-layout, stalker live-stream-layout,
 3→//           portal-collection-live-shell
 4→//
 5→// Include this mixin in a component's SCSS to get the shared flex host+sidebar
 6→// skeleton, then add only the component-specific rules underneath.
 7→//
 8→// Usage (after adding libs/ui/styles to stylePreprocessorOptions.includePaths):
 9→//   @use 'portal-layout' as portal;
10→//   @include portal.live-layout;
11→
12→@mixin live-layout {
13→    :host {
14→        display: flex;
15→        flex-direction: row;
16→        overflow: hidden;
17→        height: 100%;
18→        width: 100%;
19→    }
20→
21→    // ─── Sidebar ─────────────────────────────────────────────────────────────
22→    .sidebar {
23→        // Width controlled by the resizable directive at runtime
24→        width: 400px;
25→        min-width: 250px;
26→        max-width: 600px;
27→        border-right: 1px solid var(--app-separator);
28→        display: flex;
29→        flex-direction: column;
30→        flex-shrink: 0;
31→        overflow: hidden;
32→        position: relative;
33→        container-type: inline-size;
34→
35→        app-category-view {
36→            flex: 1;
37→            overflow-y: auto;
38→            overflow-x: hidden;
39→            margin-right: 2px;
40→        }
41→    }
42→
43→    // ─── Main content column ─────────────────────────────────────────────────
44→    .content-container {
45→        flex: 1;
46→        display: flex;
47→        flex-direction: column;
48→        overflow: hidden;
49→        min-height: 0;
50→    }
51→
52→    .video-player {
53→        flex: 1 1 0;
54→        min-height: 0;
55→        overflow: hidden;
56→        display: flex;
57→
58→        > app-web-player-view {
59→            flex: 1;
60→            min-height: 0;
61→        }
62→    }
63→
64→    .epg {
65→        flex: 1 1 0;
66→        min-height: 0;
67→        overflow: hidden;
68→    }
69→
70→    .epg-content {
71→        height: 100%;
72→        min-height: 0;
73→        overflow: hidden;
74→        display: flex;
75→        flex-direction: column;
76→
77→        > app-epg-view {
78→            flex: 1;
79→            min-height: 0;
80→        }
81→    }
82→
83→    // ─── Fix artplayer sizing when nested inside .video-player ───────────────
84→    ::ng-deep {
85→        .video-player
86→            > app-web-player-view
87→            > app-art-player
88→            > .artplayer-container {
89→            height: 100% !important;
90→            width: 100% !important;
91→        }
92→    }
93→}
94→

 1→// ─── Shared sidebar + sidebar-header styles ───────────────────────────────────
 2→// Plain CSS rules (not a mixin) used for M3U/legacy sidebar layouts.
 3→//
 4→// Usage (after adding libs/ui/styles to stylePreprocessorOptions.includePaths):
 5→//   @use 'portal-sidebar';   (no alias needed — no exported members to call)
 6→
 7→.sidebar {
 8→    // Width is controlled by the resizable directive
 9→    // Default fallback if directive not applied
10→    width: 400px;
11→    min-width: 250px;
12→    max-width: 600px;
13→    border-right: 1px solid var(--app-separator);
14→    display: flex;
15→    flex-direction: column;
16→    flex-shrink: 0; // Prevent sidebar from shrinking
17→
18→    .sidebar-header {
19→        padding: 8px 12px;
20→        background: var(--app-widget-header-bg, var(--mat-sys-surface-container-high));
21→        border-bottom: 1px solid var(--app-separator);
22→        app-region: drag;
23→        display: flex;
24→        align-items: center;
25→        gap: 8px;
26→
27→        h2 {
28→            margin: 0;
29→            font-size: 0.94rem;
30→            font-weight: 600;
31→            letter-spacing: -0.01em;
32→            color: var(--mat-sys-on-surface);
33→            flex: 1;
34→        }
35→
36→        button {
37→            app-region: no-drag;
38→        }
39→
40→        .switcher {
41→            flex: 1;
42→            min-width: 0;
43→        }
44→
45→        .manage-categories-btn {
46→            margin-left: auto;
47→        }
48→    }
49→}
50→

 1→:host {
 2→    display: flex;
 3→    flex-direction: column;
 4→    width: 100%;
 5→    height: 100%;
 6→    container-type: inline-size;
 7→}
 8→
 9→::ng-deep {
10→    .mat-mdc-tab.mdc-tab {
11→        padding: 0 5px;
12→    }
13→}
14→
15→.loading-container {
16→    display: flex;
17→    flex-direction: column;
18→    align-items: center;
19→    justify-content: center;
20→    height: calc(100vh - 120px);
21→    text-align: center;
22→}
23→
24→.loading-spinner {
25→    font-size: 48px;
26→    width: 48px;
27→    height: 48px;
28→    animation: spin 1.5s linear infinite;
29→    opacity: 0.7;
30→    margin-bottom: 16px;
31→}
32→
33→.loading-text {
34→    font-size: 1rem;
35→    opacity: 0.7;
36→}
37→
38→@keyframes spin {
39→    from {
40→        transform: rotate(0deg);
41→    }
42→    to {
43→        transform: rotate(360deg);
44→    }
45→}
46→
47→@media only screen and (max-width: 599px) {
48→    .tab-title {
49→        display: none;
