  1→// ============================================================================
  2→// Netflix-style Detail View - Cinematic Streaming Design
  3→// ============================================================================
  4→
  5→:host {
  6→    --poster-width: 220px;
  7→    --poster-shadow: 0 8px 40px rgba(0, 0, 0, 0.15);
  8→    --content-max-width: 1400px;
  9→
 10→    // Light theme colors (default - no .dark-theme class on body)
 11→    --hero-gradient-start: rgba(255, 250, 245, 0);
 12→    --hero-gradient-mid: rgba(255, 250, 245, 0.75);
 13→    --hero-gradient-end: rgba(255, 250, 245, 1);
 14→    --surface-bg: #fffaf5;
 15→    --text-primary: #1a1a1a;
 16→    --text-secondary: rgba(26, 26, 26, 0.75);
 17→    --text-muted: rgba(26, 26, 26, 0.5);
 18→    --accent-color: #b81d24;
 19→    --tag-bg: rgba(0, 0, 0, 0.06);
 20→    --tag-border: rgba(0, 0, 0, 0.12);
 21→
 22→    width: 100%;
 23→    height: 100%;
 24→    display: block;
 25→    overflow: hidden;
 26→    background: var(--surface-bg);
 27→    color: var(--text-primary);
 28→}
 29→
 30→// Dark theme overrides - cinematic dark mode
 31→:host-context(.dark-theme) {
 32→    --hero-gradient-start: rgba(20, 20, 20, 0);
 33→    --hero-gradient-mid: rgba(20, 20, 20, 0.7);
 34→    --hero-gradient-end: rgba(20, 20, 20, 1);
 35→    --surface-bg: #141414;
 36→    --text-primary: #fff;
 37→    --text-secondary: rgba(255, 255, 255, 0.7);
 38→    --text-muted: rgba(255, 255, 255, 0.5);
 39→    --accent-color: #e50914;
 40→    --tag-bg: rgba(255, 255, 255, 0.1);
 41→    --tag-border: rgba(255, 255, 255, 0.2);
 42→    --poster-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
 43→}
