 45→// ============================================================================
 46→// Hero Section - Full container with backdrop
 47→// ============================================================================
 48→
 49→.hero {
 50→    position: relative;
 51→    width: 100%;
 52→    height: 100%;
 53→    overflow: hidden;
 54→    background: var(
 55→        --surface-bg
 56→    ); // Solid background prevents any bleed-through
 57→
 58→    // Floating back button over backdrop
 59→    &__back-button {
 60→        position: absolute;
 61→        top: 16px;
 62→        left: 16px;
 63→        z-index: 10;
 64→        display: flex;
 65→        align-items: center;
 66→        justify-content: center;
 67→        width: 40px;
 68→        height: 40px;
 69→        border-radius: 50%;
 70→        background: rgba(0, 0, 0, 0.5);
 71→        backdrop-filter: blur(8px);
 72→        border: none;
 73→        cursor: pointer;
 74→        transition: all 0.2s ease;
 75→        color: #fff;
 76→
 77→        &:hover {
 78→            background: rgba(0, 0, 0, 0.7);
 79→            transform: scale(1.05);
 80→        }
 81→
 82→        mat-icon {
 83→            font-size: 24px;
 84→            width: 24px;
 85→            height: 24px;
 86→        }
 87→    }
 88→
 89→    // Backdrop image layer - fixed at top, never repeats
 90→    &__backdrop {
 91→        position: absolute;
 92→        top: 0;
 93→        left: 0;
 94→        right: 0;
 95→        bottom: auto; // Only use height, not bottom
 96→        height: 60%;
 97→        background-size: cover;
 98→        background-position: center 20%;
 99→        background-repeat: no-repeat;
100→        z-index: 0;
101→        overflow: hidden;
102→
103→        // Fallback blur effect when using poster as backdrop
104→        &--blurred {
105→            filter: blur(40px) saturate(1.3);
106→            transform: scale(1.4);
107→            height: 65%;
108→        }
109→    }
110→
111→    // Gradient overlays for text legibility
112→    &__vignette {
113→        position: absolute;
114→        top: 0;
115→        left: 0;
116→        right: 0;
117→        bottom: 0; // Full height to cover everything
118→        z-index: 1;
119→        pointer-events: none;
120→        background: linear-gradient(
121→            to bottom,
122→            transparent 0%,
123→            transparent 35%,
124→            var(--surface-bg) 55%,
125→            var(--surface-bg) 100%
126→        );
127→
128→        // Top area gradient for text legibility over backdrop
129→        &::before {
130→            content: '';
131→            position: absolute;
132→            top: 0;
133→            left: 0;
134→            right: 0;
135→            height: 60%;
136→            background: linear-gradient(
137→                to top,
138→                var(--hero-gradient-end) 0%,
139→                var(--hero-gradient-mid) 50%,
140→                var(--hero-gradient-start) 100%
141→            );
142→        }
143→
144→        // Side fade for poster area
145→        &::after {
146→            content: '';
147→            position: absolute;
148→            top: 0;
149→            left: 0;
150→            height: 50%;
151→            width: 40%;
152→            background: linear-gradient(
153→                to right,
154→                var(--hero-gradient-mid) 0%,
155→                var(--hero-gradient-start) 100%
156→            );
157→        }
158→    }
159→
160→    // Scrollable content area
161→    &__content {
162→        position: absolute;
163→        inset: 0;
164→        z-index: 2;
165→        display: flex;
166→        gap: 32px;
167→        align-items: flex-start;
168→        padding: 140px 40px 60px;
169→        max-width: var(--content-max-width);
170→        margin: 0 auto;
171→        overflow-y: auto;
172→        overflow-x: hidden;
173→        box-sizing: border-box;
174→
175→        // Hide scrollbar but keep functionality
176→        scrollbar-width: none;
177→        -ms-overflow-style: none;
178→        &::-webkit-scrollbar {
179→            display: none;
180→        }
181→    }
182→
183→    // Error state
184→    &__error {
185→        flex-direction: column;
186→        align-items: center;
187→        justify-content: center;
188→        text-align: center;
189→        gap: 16px;
