306→@media (prefers-reduced-motion: reduce) {
307→    .play-btn,
308→    .play-btn::before,
309→    .play-btn mat-icon,
310→    .play-btn__icon-shell {
311→        animation: none !important;
312→        transition-duration: 1ms !important;
313→    }
