  1→import { Component, computed, input, output } from '@angular/core';
  2→import { MatCardModule } from '@angular/material/card';
  3→import { MatIcon } from '@angular/material/icon';
  4→import { MatPaginatorModule, PageEvent } from '@angular/material/paginator';
  5→import { MatTooltip } from '@angular/material/tooltip';
  6→import { TranslatePipe } from '@ngx-translate/core';
  7→import {
  8→    ProgressCapsuleComponent,
  9→    WatchedBadgeComponent,
 10→} from 'components';
 11→import { PlaylistErrorViewComponent } from '../playlist-error-view/playlist-error-view.component';
