 13→interface GridListItem {
 14→    id?: number | string;
 15→    is_series?: number | string | boolean;
 16→    xtream_id?: number | string;
 17→    series_id?: number | string;
 18→    stream_id?: number | string;
 19→    category_id?: number | string;
 20→    poster_url?: string;
 21→    cover?: string;
 22→    title?: string;
 23→    o_name?: string;
 24→    name?: string;
 25→    rating?: string | number;
 26→    rating_imdb?: string | number;
 27→    progress?: number;
 28→    isWatched?: boolean;
 29→    hasSeriesProgress?: boolean;
