 33→@Component({
 34→    selector: 'app-grid-list',
 35→    template: `<div
 36→            class="grid grid-cols-[repeat(auto-fill,minmax(148px,1fr))] gap-4"
 37→        >
 38→            @if (isLoading()) {
 39→                @for (row of skeletonRows(); track row) {
 40→                    <div class="grid-skeleton-card" aria-hidden="true">
 41→                        <div class="grid-skeleton-thumb">
 42→                            <span class="grid-skeleton-badge"></span>
 43→                        </div>
 44→                        <div class="grid-skeleton-title">
 45→                            <span
 46→                                class="grid-skeleton-line grid-skeleton-line--primary"
 47→                            ></span>
 48→                            <span
 49→                                class="grid-skeleton-line grid-skeleton-line--secondary"
 50→                            ></span>
 51→                        </div>
 52→                    </div>
 53→                }
 54→            } @else {
 55→                @for (item of items(); track $index) {
 56→                    @let i = $any(item);
 57→                    <mat-card (click)="itemClicked.emit(item)">
 58→                        @let poster = i.poster_url ?? i.cover;
 59→                        <div class="card-thumbnail-container">
 60→                            <img
 61→                                class="stream-icon"
 62→                                [src]="
 63→                                    poster ||
 64→                                    './assets/images/default-poster.png'
 65→                                "
 66→                                (error)="
 67→                                    $event.target.src =
 68→                                        './assets/images/default-poster.png'
 69→                                "
 70→                                loading="lazy"
 71→                                alt="logo"
 72→                            />
 73→                            @if (i.progress && i.progress > 0) {
 74→                                <app-progress-capsule [progress]="i.progress" />
 75→                            }
 76→                            @if (i.isWatched) {
 77→                                <app-watched-badge
 78→                                    [isWatched]="true"
 79→                                    icon="check_circle"
 80→                                />
 81→                            } @else if (i.hasSeriesProgress) {
 82→                                <app-watched-badge
 83→                                    [isWatched]="true"
 84→                                    icon="remove_red_eye"
 85→                                />
 86→                            }
 87→                        </div>
 88→                        @let rating = i.rating ?? i.rating_imdb;
 89→                        @if (rating) {
 90→                            <div
 91→                                class="rating"
 92→                                [matTooltip]="'XTREAM.IMDB_RATING' | translate"
 93→                            >
 94→                                <mat-icon>star</mat-icon>{{ rating }}
 95→                            </div>
 96→                        }
 97→                        @let title = i.title ?? i.o_name ?? i.name;
 98→                        <mat-card-actions>
 99→                            <div class="title">
100→                                {{ title || 'No name' }}
101→                            </div>
102→                        </mat-card-actions>
103→                    </mat-card>
104→                } @empty {
105→                    <div class="grid-empty-state">
106→                        <app-playlist-error-view
107→                            [title]="
108→                                'PORTALS.ERROR_VIEW.EMPTY_CATEGORY.TITLE'
109→                                    | translate
110→                            "
111→                            [description]="
112→                                'PORTALS.ERROR_VIEW.EMPTY_CATEGORY.DESCRIPTION'
113→                                    | translate
114→                            "
115→                            [showActionButtons]="false"
116→                            [viewType]="'EMPTY_CATEGORY'"
117→                        />
118→                    </div>
119→                }
120→            }
121→        </div>
122→        @if (showPaginator() && items()?.length > 0) {
123→            <mat-paginator
124→                [pageIndex]="pageIndex()"
125→                [length]="totalPages() * limit()"
126→                [pageSize]="limit()"
127→                [pageSizeOptions]="pageSizeOptions()"
128→                (page)="pageChange.emit($event)"
129→                aria-label="Select page"
130→            />
131→        } `,
132→    styleUrl: './grid-list.component.scss',
133→    imports: [
134→        TranslatePipe,
135→        PlaylistErrorViewComponent,
136→        MatCardModule,
137→        MatIcon,
138→        MatTooltip,
139→        MatPaginatorModule,
140→        ProgressCapsuleComponent,
141→        WatchedBadgeComponent,
142→    ],
143→})
144→export class GridListComponent {
145→    readonly items = input<GridListItem[]>();
146→    readonly isLoading = input<boolean>();
147→    readonly showPaginator = input(true);
148→    readonly itemClicked = output<GridListItem>();
149→    readonly pageChange = output<PageEvent>();
150→
151→    readonly pageIndex = input<number>();
152→    readonly totalPages = input<number>();
153→    readonly limit = input<number>();
154→    readonly pageSizeOptions = input<number[]>();
155→
156→    readonly skeletonRows = computed(() => {
157→        const preferredCount = this.limit() ?? 12;
158→        const count = Math.max(8, Math.min(18, preferredCount));
159→        return Array.from({ length: count }, (_, index) => index);
160→    });
161→}
