@use '@angular/material' as mat;
@use '../../../../../../ui/styles/portal-layout' as portal;
@use '../../../../../../ui/styles/portal-sidebar';

@include portal.live-layout;

.search-panel {
    padding: 8px 12px;
    flex-shrink: 0;
    height: 56px;
    box-sizing: border-box;
}

.search-bar {
    width: 100%;
    @include mat.form-field-density(-5);
}

::ng-deep {
    .search-bar {
        div {
            border-radius: 20px;
        }
    }

    div[matformfieldlineripple] {
        display: none;
    }
}

.channels-list {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 4px 8px 12px;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.loading-indicator {
    display: flex;
    justify-content: center;
    padding: 16px;
}

.load-more-epg {
    display: flex;
    justify-content: center;
    padding: 8px 0;
}

@container (max-width: 350px) {
    .channels-list {
        padding-inline: 6px;
    }
}

