    cursor: pointer;
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;

    &:hover {
        transform: translateY(-3px);
        box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
    }
}

@mixin thumbnail-wrapper {
    position: relative;
    border-radius: 8px;
    overflow: hidden;

    .poster {
        width: 100%;
        aspect-ratio: 2/3;
        object-fit: cover;
        display: block;
    }

    .poster-placeholder {
        width: 100%;
        aspect-ratio: 2/3;
        display: flex;
        align-items: center;
        justify-content: center;
        background: rgba(128, 128, 128, 0.1);

        mat-icon {
            font-size: 36px;
            width: 36px;
            height: 36px;
            opacity: 0.25;
        }
    }
}

