// Shared content grid and card styles
//
// Usage (after adding libs/ui/styles to stylePreprocessorOptions.includePaths):
//   @use 'content-grid' as grid;
//   @include grid.content-grid;
//   @include grid.content-card;

@mixin content-grid($min-width: 140px, $gap: 20px) {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax($min-width, 1fr));
    gap: $gap;
}

@mixin content-card {
    cursor: pointer;
    border-radius: 10px;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;

    &:hover {
        transform: translateY(-3px);
        box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
    }
}

@let isEmbeddedPlayer = usesEmbeddedPlayer();

@if (selectedCategoryId()) {
    <div
        class="sidebar"
        appResizable
        [minWidth]="250"
        [maxWidth]="600"
        [defaultWidth]="400"
        storageKey="sidebar-width"
    >
        <div class="sidebar-header">
            <div class="category-heading">
                <h2 class="category-title">
                    {{ selectedCategoryInfo()?.name }}
                </h2>
                @if (selectedCategoryInfo()?.count) {
                    <span class="category-count">{{
                        selectedCategoryInfo()?.count
                    }}</span>
                }
            </div>
            <button
                mat-icon-button
                [matMenuTriggerFor]="channelSortMenu"
                [matTooltip]="'Sort: ' + liveChannelSortLabel()"
                aria-label="Sort channels"
            >
                <mat-icon>sort_by_alpha</mat-icon>
            </button>
            <mat-menu #channelSortMenu="matMenu">
                <button
                    mat-menu-item
                    (click)="setLiveChannelSortMode('server')"
                >
                    <span>Server Order</span>
                    @if (liveChannelSortMode() === 'server') {
                        <mat-icon>check</mat-icon>
                    }
                </button>
                <button
                    mat-menu-item
                    (click)="setLiveChannelSortMode('name-asc')"
                >
                    <span>Name A-Z</span>
                    @if (liveChannelSortMode() === 'name-asc') {
                        <mat-icon>check</mat-icon>
                    }
                </button>
                <button
                    mat-menu-item
                    (click)="setLiveChannelSortMode('name-desc')"
                >
                    <span>Name Z-A</span>
                    @if (liveChannelSortMode() === 'name-desc') {
                        <mat-icon>check</mat-icon>
                    }
                </button>
            </mat-menu>
        </div>
        <app-portal-channels-list
            [sortMode]="liveChannelSortMode()"
            [searchTermInput]="workspaceSearchTerm()"
            (playClicked)="playLive($event)"
        />
    </div>
}
<div class="content-container">
    @if (!selectedCategoryId()) {
        <app-portal-empty-state
            icon="live_tv"
            [message]="'PORTALS.SELECT_CATEGORY' | translate"
        />
    } @else if (streamUrl) {
        @if (isEmbeddedPlayer) {
            <div class="video-player">
                <app-web-player-view [streamUrl]="streamUrl" />
            </div>
        }
        <div class="epg">
            <div class="epg-content">
                @if (epgItems().length > 0) {
                    <app-epg-view [epgItems]="epgItems()" />
                }
            </div>
        </div>
    } @else {
        <app-portal-empty-state
            icon="live_tv"
            [message]="'CHANNELS.SELECT_CHANNEL_PLAYBACK' | translate"
        />
    }
</div>

@let isEmbeddedPlayer = usesEmbeddedPlayer();

@if (stalkerStore.selectedCategoryId()) {
    <div
        class="sidebar"
        appResizable
        [minWidth]="250"
        [maxWidth]="600"
        [defaultWidth]="400"
        storageKey="sidebar-width"
    >
        <div class="sidebar-header">
            <h2>{{ selectedCategoryTitle() }}</h2>
        </div>

        <div #scrollContainer class="channels-list">
            @if (searchTerm() && visibleChannels().length === 0) {
                <div class="empty-search-state">
                    <app-portal-empty-state
                        icon="search_off"
                        [message]="'CHANNELS.NO_SEARCH_RESULTS' | translate"
                    />
                </div>
            } @else {
                @for (item of visibleChannels(); track item.id ?? $index) {
                    <app-channel-list-item
                        [name]="item.o_name || item.name"
                        [logo]="item.logo"
                        [selected]="isSelectedChannel(item)"
                        [epgProgram]="
                            epgPreviewPrograms.get(
                                normalizeStalkerEntityId(item.id)
                            ) ?? null
                        "
                        [progressPercentage]="
                            currentProgramsProgress.get(
                                normalizeStalkerEntityId(item.id)
                            ) ?? 0
                        "
                        [showFavoriteButton]="true"
                        [showProgramInfoButton]="false"
                        [isFavorite]="
                            favorites.get(normalizeStalkerEntityId(item.id)) ??
                            false
                        "
                        (clicked)="playChannel(item)"
                        (favoriteToggled)="toggleFavorite(item)"
                    />
                }
            }

            @if (isLoadingMore()) {
                <div class="loading-indicator">
                    <mat-spinner diameter="24" />
                </div>
            }
        </div>
    </div>
}

<div class="content-container">
    @if (!stalkerStore.selectedCategoryId()) {
        <app-portal-empty-state
            icon="live_tv"
            [message]="'PORTALS.SELECT_CATEGORY' | translate"
        />
    } @else if (stalkerStore.selectedItem()) {
        @if (streamUrl && isEmbeddedPlayer) {
            <div class="video-player">
                <app-web-player-view [streamUrl]="streamUrl" />
            </div>
        }
        <div class="epg">
            <div class="epg-content">
                <app-epg-view [epgItems]="epgItems()" />
                @if (isLoadingEpg()) {
                    <div class="loading-indicator">
                        <mat-spinner diameter="24" />
                    </div>
                }
                @if (hasMoreEpg() && !isLoadingEpg()) {
                    <div class="load-more-epg">
                        <button mat-button (click)="loadMoreEpg()">
                            {{ 'CHANNELS.LOAD_MORE' | translate }}
                        </button>
                    </div>
                }
            </div>
        </div>
    } @else {
        <app-portal-empty-state
            icon="live_tv"
            [message]="'CHANNELS.SELECT_CHANNEL_PLAYBACK' | translate"
        />
    }
</div>

