  1→import {
  2→    ChangeDetectionStrategy,
  3→    ChangeDetectorRef,
  4→    Component,
  5→    computed,
  6→    effect,
  7→    ElementRef,
  8→    inject,
  9→    NgZone,
 10→    OnDestroy,
 11→    signal,
 12→    viewChild,
 13→} from '@angular/core';
 14→import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
 15→import { MatButton } from '@angular/material/button';
 16→import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
 17→import { MatSnackBar } from '@angular/material/snack-bar';
 18→import { TranslatePipe, TranslateService } from '@ngx-translate/core';
 19→import {
 20→    ChannelListItemComponent,
 21→    ResizableDirective,
 22→} from 'components';
 23→import { PlaylistsService } from 'services';
 24→import { EpgItem, EpgProgram } from 'shared-interfaces';
 25→import { EpgViewComponent, WebPlayerViewComponent } from 'shared-portals';
 26→import {
 27→    PORTAL_PLAYER,
 28→    createLogger,
 29→    getAdjacentChannelItem,
 30→    getChannelItemByNumber,
 31→} from '@iptvnator/portal/shared/util';
 32→import {
 33→    PortalEmptyStateComponent,
 34→} from '@iptvnator/portal/shared/ui';
 35→import {
 36→    StalkerFavoriteItem,
 37→    StalkerItvChannel,
 38→    normalizeStalkerEntityId,
 39→    StalkerStore,
 40→} from '@iptvnator/portal/stalker/data-access';
 41→
 42→@Component({
 43→    selector: 'app-stalker-live-stream-layout',
 44→    templateUrl: './stalker-live-stream-layout.component.html',
 45→    styleUrls: ['./stalker-live-stream-layout.component.scss'],
 46→    imports: [
 47→        ChannelListItemComponent,
 48→        EpgViewComponent,
 49→        MatButton,
 50→        MatProgressSpinnerModule,
 51→        PortalEmptyStateComponent,
 52→        ResizableDirective,
 53→        TranslatePipe,
 54→        WebPlayerViewComponent,
 55→    ],
 56→    changeDetection: ChangeDetectionStrategy.OnPush,
 57→})
 58→export class StalkerLiveStreamLayoutComponent implements OnDestroy {
 59→    readonly stalkerStore = inject(StalkerStore);
 60→    private readonly playlistService = inject(PlaylistsService);
 61→    private readonly portalPlayer = inject(PORTAL_PLAYER);
 62→    private readonly snackBar = inject(MatSnackBar);
 63→    private readonly translate = inject(TranslateService);
 64→    private readonly logger = createLogger('StalkerLiveStream');
 65→    readonly selectedCategoryTitle = this.stalkerStore.getSelectedCategoryName;
 66→
 67→    /** Channels */
 68→    readonly itvChannels = this.stalkerStore.itvChannels;
 69→    readonly searchTerm = computed(() =>
 70→        this.stalkerStore.searchPhrase().trim().toLowerCase()
 71→    );
 72→    readonly visibleChannels = computed(() => {
 73→        const channels = this.itvChannels();
 74→        const term = this.searchTerm();
 75→
 76→        if (!term) {
 77→            return channels;
 78→        }
 79→
 80→        return channels.filter((item) =>
 81→            `${item.o_name ?? ''} ${item.name ?? ''}`
 82→                .toLowerCase()
 83→                .includes(term)
 84→        );
 85→    });
 86→    readonly hasMoreItems = this.stalkerStore.hasMoreChannels;
 87→    readonly isLoadingMore = signal(false);
 88→
 89→    readonly selectedChannelId = this.stalkerStore.selectedItvId;
 90→    protected readonly normalizeStalkerEntityId = normalizeStalkerEntityId;
 91→
 92→    /** Player */
 93→    readonly usesEmbeddedPlayer = computed(() =>
 94→        this.portalPlayer.isEmbeddedPlayer()
 95→    );
 96→    streamUrl = '';
 97→
 98→    /** EPG */
 99→    readonly epgItems = signal<EpgItem[]>([]);
100→    readonly isLoadingEpg = signal(false);
101→    readonly hasMoreEpg = signal(false);
102→    private epgPageSize = 10;
103→    private epgChannelId: number | string | null = null;
104→
105→    /** Channel list EPG preview */
106→    readonly epgPreviewPrograms = new Map<string | number, EpgProgram>();
107→    readonly currentProgramsProgress = new Map<string | number, number>();
108→    private readonly requestedEpgChannels = new Set<string | number>();
109→    private readonly cdr = inject(ChangeDetectorRef);
110→    private readonly ngZone = inject(NgZone);
111→
112→    /** Favorites */
113→    readonly favorites = new Map<string | number, boolean>();
114→
115→    /** Scroll */
116→    readonly scrollContainer = viewChild<ElementRef>('scrollContainer');
117→    private scrollListener: (() => void) | null = null;
118→    private unsubscribeRemoteChannelChange?: () => void;
119→    private unsubscribeRemoteCommand?: () => void;
120→
121→    constructor() {
122→        // Load favorites for current playlist
123→        this.playlistService
124→            .getPortalFavorites(this.stalkerStore.currentPlaylist()?._id)
125→            .pipe(takeUntilDestroyed())
126→            .subscribe((favs) => {
127→                favs.forEach((fav: StalkerFavoriteItem) => {
128→                    if (fav.id !== undefined) {
129→                        this.favorites.set(
130→                            normalizeStalkerEntityId(fav.id),
131→                            true
132→                        );
133→                    }
134→                });
135→            });
136→
137→        // Reset channels/page on category change
138→        effect(() => {
139→            this.stalkerStore.selectedCategoryId();
140→            this.stalkerStore.setItvChannels([]);
141→            this.stalkerStore.setPage(0);
142→            this.clearEpgPreviewMaps();
143→        });
144→
145→        // Reset loading state when channels load + check viewport fill + load EPG previews
146→        effect(() => {
147→            const channels = this.visibleChannels();
148→            if (channels.length > 0) {
149→                this.isLoadingMore.set(false);
150→                if (!this.searchTerm()) {
151→                    setTimeout(() => this.checkIfNeedsMoreContent(), 100);
152→                }
153→                this.loadEpgPreviewsForChannels(channels);
154→            }
155→        });
156→
157→        // Setup scroll listener when container becomes available
158→        effect(() => {
159→            const container = this.scrollContainer();
160→            if (container) {
161→                this.setupScrollListener();
162→            }
163→        });
164→
165→        effect(() => {
166→            if (!window.electron?.updateRemoteControlStatus) {
167→                return;
168→            }
169→
170→            const selectedItem = this.stalkerStore.selectedItem();
171→            const selectedType = this.stalkerStore.selectedContentType();
172→            const channels = this.visibleChannels();
173→            const epgItems = this.epgItems();
174→
175→            if (selectedType !== 'itv' || !selectedItem?.id) {
176→                window.electron.updateRemoteControlStatus({
177→                    portal: 'stalker',
178→                    isLiveView: false,
179→                    supportsVolume: false,
180→                });
181→                return;
182→            }
183→
184→            const currentIndex = channels.findIndex(
185→                (item) => Number(item.id) === Number(selectedItem.id)
186→            );
187→            const currentProgram = epgItems?.[0];
188→
189→            window.electron.updateRemoteControlStatus({
190→                portal: 'stalker',
191→                isLiveView: true,
192→                channelName: selectedItem.o_name || selectedItem.name,
193→                channelNumber: currentIndex >= 0 ? currentIndex + 1 : undefined,
194→                epgTitle: currentProgram?.title,
195→                epgStart: currentProgram?.start,
196→                epgEnd: currentProgram?.end,
197→                supportsVolume: false,
198→            });
199→        });
200→
201→        if (window.electron?.onChannelChange) {
202→            const unsubscribe = window.electron.onChannelChange(
203→                (data: { direction: 'up' | 'down' }) => {
