    margin: 1px 0;
}

mat-icon {
    margin-right: 0;
    font-size: 18px !important;
    width: 18px !important;
    height: 18px !important;
}

a.mat-mdc-list-item.mdc-list-item {
    padding-right: 0;
}

.portal-status-container {
    app-region: drag;
    margin: -4px -4px 0;
    height: 42px;
    display: flex;
    align-items: center;
