186→        showCaptions: false,
187→        showExternalPlaybackBar: true,
188→        theme: Theme.SystemTheme,
189→        mpvPlayerPath: '',
190→        mpvReuseInstance: false,
191→        vlcPlayerPath: '',
192→        remoteControl: false,
193→        remoteControlPort: [
194→            8765,
195→            [
196→                Validators.required,
197→                Validators.min(1),
198→                Validators.max(65535),
199→                Validators.pattern(/^\d+$/),
200→            ],
201→        ],
202→    });
203→
204→    /** Form array with epg sources */
205→    epgUrl = this.settingsForm.get('epgUrl') as FormArray;
206→
207→    /** Local IP addresses for remote control URL display */
208→    localIpAddresses = signal<string[]>([]);
209→
210→    /** Currently visible QR code IP (null = none visible) */
211→    visibleQrCodeIp = signal<string | null>(null);
212→
213→    private settingsStore = inject(SettingsStore);
214→    private sectionObserver?: IntersectionObserver;
215→
216→    readonly sectionNavItems: SettingsSection[] = [
217→        {
218→            id: 'general',
219→            label: 'SETTINGS.NAV_GENERAL',
220→            icon: 'tune',
221→            visible: true,
222→        },
223→        {
224→            id: 'playback',
225→            label: 'SETTINGS.NAV_PLAYBACK',
226→            icon: 'play_circle',
227→            visible: true,
228→        },
229→        {
230→            id: 'epg',
231→            label: 'SETTINGS.NAV_EPG',
232→            icon: 'calendar_month',
233→            visible: this.isDesktop,
234→        },
235→        {
236→            id: 'remote-control',
237→            label: 'SETTINGS.NAV_REMOTE',
238→            icon: 'smartphone',
239→            visible: this.isDesktop,
240→        },
241→        {
242→            id: 'data',
243→            label: 'SETTINGS.NAV_DATA',
244→            icon: 'swap_horiz',
245→            visible: true,
246→        },
247→        {
248→            id: 'about',
249→            label: 'SETTINGS.NAV_ABOUT',
250→            icon: 'info',
251→            visible: true,
252→        },
253→    ];
254→
255→    constructor() {
256→        effect(
257→            () => {
258→                const sectionId = this.settingsCtx.pendingScrollTarget();
259→                if (!sectionId || typeof document === 'undefined') {
260→                    return;
261→                }
262→
263→                document
264→                    .getElementById(sectionId)
265→                    ?.scrollIntoView({ behavior: 'smooth', block: 'start' });
266→                this.settingsCtx.clearPendingScrollTarget();
267→            },
268→            { injector: this.injector }
269→        );
270→
271→        effect(
272→            (onCleanup) => {
273→                const activeSectionId = this.activeSection();
274→                const activeSectionElement =
275→                    this.elementRef.nativeElement.querySelector(
276→                        `#${activeSectionId}`
277→                    ) as HTMLElement | null;
278→
279→                if (!activeSectionElement) {
280→                    return;
281→                }
282→
283→                const animation = activeSectionElement.animate(
284→                    [
285→                        {
286→                            boxShadow:
287→                                'inset 0 0 0 1px var(--settings-group-active-ring), 0 8px 18px -24px var(--settings-group-active-glow)',
288→                        },
289→                        {
290→                            boxShadow:
291→                                'inset 0 0 0 1px var(--settings-group-active-ring), 0 12px 22px -24px var(--settings-group-active-glow)',
292→                        },
293→                        {
294→                            boxShadow:
295→                                'inset 0 0 0 1px var(--settings-group-active-ring), 0 8px 18px -24px var(--settings-group-active-glow)',
296→                        },
297→                    ],
298→                    {
299→                        duration: 260,
300→                        easing: 'ease-out',
301→                    }
302→                );
303→
304→                onCleanup(() => animation.cancel());
305→            },
306→            { injector: this.injector }
307→        );
308→    }
309→
310→    get sectionNav(): SettingsSection[] {
311→        return this.sectionNavItems.filter((section) => section.visible);
312→    }
313→
314→    /**
315→     * Reads the config object from the browsers
316→     * storage (indexed db)
317→     */
318→    async ngOnInit(): Promise<void> {
319→        // Wait for settings to load before setting the form
320→        await this.settingsStore.loadSettings();
321→        this.setSettings();
322→        this.checkAppVersion();
323→        this.fetchLocalIpAddresses();
324→
325→        if (!this.isDialog) {
326→            this.settingsCtx.setSections(this.sectionNav);
327→        }
