337→    /**
338→     * Fetches local IP addresses for remote control URL display
339→     */
340→    async fetchLocalIpAddresses(): Promise<void> {
341→        if (window.electron?.getLocalIpAddresses) {
342→            const addresses = await window.electron.getLocalIpAddresses();
343→            this.localIpAddresses.set(addresses);
344→        }
