346→
347→    /**
348→     * Toggle QR code visibility for a given IP address
349→     */
350→    toggleQrCode(ip: string): void {
351→        if (this.visibleQrCodeIp() === ip) {
352→            this.visibleQrCodeIp.set(null);
353→        } else {
354→            this.visibleQrCodeIp.set(ip);
355→        }
356→    }
357→
358→    /**
359→     * Sets saved settings from the indexed db store
360→     */
361→    setSettings() {
362→        const currentSettings = this.settingsStore.getSettings();
363→        this.settingsForm.patchValue(currentSettings);
364→
365→        if (this.isDesktop && currentSettings.epgUrl) {
366→            this.setEpgUrls(currentSettings.epgUrl);
367→        }
368→    }
369→
370→    selectTheme(theme: Theme): void {
371→        if (this.settingsForm.value.theme === theme) {
372→            return;
373→        }
374→
375→        this.settingsForm.patchValue({ theme });
376→        this.settingsForm.get('theme')?.markAsDirty();
377→        this.settingsForm.markAsDirty();
378→    }
379→
380→    /**
381→     * Sets the epg urls to the form array
382→     * @param epgUrls urls of the EPG sources
383→     */
384→    setEpgUrls(epgUrls: string[] | string): void {
385→        const URL_REGEX = /^(http|https|file):\/\/[^ "]+$/;
386→
387→        const urls = Array.isArray(epgUrls) ? epgUrls : [epgUrls];
388→        const filteredUrls = urls
389→            .map((url) => url.trim())
390→            .filter((url) => url !== '');
391→
392→        filteredUrls.forEach((url) => {
393→            this.epgUrl.push(
394→                new FormControl(url, [Validators.pattern(URL_REGEX)])
395→            );
396→        });
397→    }
398→
399→    /**
400→     * Checks whether the latest version of the application
401→     * is used and updates the version message in the
402→     * settings UI
403→     */
404→    checkAppVersion(): void {
405→        this.settingsService
406→            .getAppVersion()
407→            .pipe(take(1))
408→            .subscribe((version) => this.showVersionInformation(version));
409→    }
410→
411→    /**
412→     * Updates the message in settings UI about the used
413→     * version of the app
414→     * @param currentVersion current version of the application
415→     */
416→    showVersionInformation(currentVersion: string): void {
417→        const isOutdated = this.isCurrentVersionOutdated(currentVersion);
418→
419→        if (isOutdated) {
420→            this.updateMessage = `${
421→                this.translate.instant(
422→                    'SETTINGS.NEW_VERSION_AVAILABLE'
423→                ) as string
424→            }: ${currentVersion}`;
425→        } else {
426→            this.updateMessage = this.translate.instant(
427→                'SETTINGS.LATEST_VERSION'
428→            );
429→        }
430→    }
431→
432→    /**
433→     * Compares actual with latest version of the
434→     * application
435→     * @param latestVersion latest version
436→     * @returns returns true if an update is available
437→     */
438→    isCurrentVersionOutdated(latestVersion: string): boolean {
439→        this.version = this.dataService.getAppVersion();
440→        return this.settingsService.isVersionOutdated(
441→            this.version,
442→            latestVersion
443→        );
444→    }
445→
446→    /**
447→     * Triggers on form submit and saves the config object to
448→     * the indexed db store
449→     */
450→    onSubmit(): void {
451→        this.settingsStore.updateSettings(this.settingsForm.value).then(() => {
452→            this.applyChangedSettings();
453→
454→            if (window.electron) {
455→                window.electron.updateSettings(this.settingsForm.value);
456→
457→                // Set player paths if using external players
458→                if (this.settingsForm.value.mpvPlayerPath) {
459→                    window.electron.setMpvPlayerPath(
460→                        this.settingsForm.value.mpvPlayerPath
461→                    );
462→                }
463→                if (this.settingsForm.value.vlcPlayerPath) {
464→                    window.electron.setVlcPlayerPath(
465→                        this.settingsForm.value.vlcPlayerPath
466→                    );
467→                }
468→            }
469→        });
470→        if (this.isDialog) {
471→            this.matDialog.closeAll();
472→        }
473→    }
474→
475→    /**
476→     * Applies the changed settings to the app
477→     */
478→    applyChangedSettings(): void {
479→        this.settingsForm.markAsPristine();
480→        if (this.isDesktop) {
481→            let epgUrls = this.settingsForm.value.epgUrl;
482→            if (epgUrls) {
483→                if (!Array.isArray(epgUrls)) {
484→                    epgUrls = [epgUrls];
485→                }
486→                epgUrls = epgUrls.filter((url) => url !== '');
487→                if (epgUrls.length > 0) {
488→                    // Fetch all EPG URLs at once
489→                    this.epgService.fetchEpg(epgUrls);
490→                }
491→            }
492→        }
493→        this.translate.use(this.settingsForm.value.language);
494→        this.settingsService.changeTheme(
495→            this.settingsForm.value.theme ?? Theme.SystemTheme
496→        );
497→        this.snackBar.open(
498→            this.translate.instant('SETTINGS.SETTINGS_SAVED'),
499→            null,
500→            {
501→                duration: 2000,
502→                horizontalPosition: 'start',
503→            }
504→        );
505→    }
506→
507→    /**
508→     * Navigates back to the applications homepage
509→     */
510→    backToHome(): void {
511→        if (this.isDialog) {
512→            this.matDialog.closeAll();
513→        } else {
514→            this.router.navigateByUrl('/');
515→        }
516→    }
517→
518→    /**
519→     * Fetches and updates EPG from the given URL
520→     * @param url epg source url
521→     */
522→    refreshEpg(url: string): void {
523→        this.epgService.fetchEpg([url]);
524→    }
525→
526→    /**
527→     * Initializes new entry in form array for EPG URL
528→     */
529→    addEpgSource(): void {
530→        this.epgUrl.insert(
531→            this.epgUrl.length,
532→            new FormControl('', {
533→                validators: [
534→                    Validators.pattern(/^(http|https|file):\/\/[^ "]+$/),
535→                ],
536→            })
537→        );
538→    }
539→
540→    /**
541→     * Removes entry from form array for EPG URL
542→     * @param index index of the item to remove
543→     */
544→    removeEpgSource(index: number): void {
545→        this.epgUrl.removeAt(index);
546→        this.settingsForm.markAsDirty();
547→    }
548→
549→    /**
550→     * Clears all EPG data from database
551→     */
552→    clearEpgData(): void {
553→        this.dialogService.openConfirmDialog({
554→            title: this.translate.instant('SETTINGS.CLEAR_EPG_DIALOG.TITLE'),
555→            message: this.translate.instant(
556→                'SETTINGS.CLEAR_EPG_DIALOG.MESSAGE'
557→            ),
558→            onConfirm: async (): Promise<void> => {
559→                if (window.electron?.clearEpgData) {
560→                    await window.electron.clearEpgData();
561→                    this.snackBar.open(
562→                        this.translate.instant('SETTINGS.EPG_DATA_CLEARED'),
563→                        null,
564→                        { duration: 2000, horizontalPosition: 'start' }
565→                    );
566→                }
567→            },
568→        });
569→    }
570→
571→    exportData() {
572→        this.playlistsService
573→            .getAllData()
574→            .pipe(take(1))
575→            .subscribe((data) => {
576→                const blob = new Blob([JSON.stringify(data)], {
577→                    type: 'text/plain',
578→                });
579→                const url = window.URL.createObjectURL(blob);
580→                const link = document.createElement('a');
581→                link.href = url;
582→                link.download = 'playlists.json';
583→                link.click();
584→                window.URL.revokeObjectURL(url);
585→            });
586→    }
587→
588→    importData() {
589→        const input = document.createElement('input');
590→        input.type = 'file';
591→        input.accept = 'application/json';
592→
593→        input.addEventListener('change', (event: Event) => {
594→            const target = event.target as HTMLInputElement;
595→            const file = target.files?.[0];
596→
597→            if (file) {
598→                const reader = new FileReader();
599→                reader.onload = () => {
600→                    const contents = reader.result;
601→
602→                    try {
603→                        const parsedPlaylists: Playlist[] = JSON.parse(
604→                            contents.toString()
605→                        );
606→
607→                        if (!Array.isArray(parsedPlaylists)) {
608→                            this.snackBar.open(
609→                                this.translate.instant('SETTINGS.IMPORT_ERROR'),
610→                                null,
611→                                {
612→                                    duration: 2000,
613→                                }
614→                            );
615→                        } else {
616→                            this.store.dispatch(
617→                                PlaylistActions.addManyPlaylists({
618→                                    playlists: parsedPlaylists,
619→                                })
620→                            );
621→                        }
622→                    } catch (error) {
623→                        this.snackBar.open(
624→                            this.translate.instant('SETTINGS.IMPORT_ERROR'),
625→                            null,
626→                            {
627→                                duration: 2000,
628→                            }
629→                        );
630→                        console.error(error);
631→                    }
632→                };
633→                reader.readAsText(file);
634→            }
635→        });
636→
637→        input.click();
638→    }
639→
640→    removeAll() {
641→        this.dialogService.openConfirmDialog({
642→            title: this.translate.instant('SETTINGS.REMOVE_DIALOG.TITLE'),
643→            message: this.translate.instant('SETTINGS.REMOVE_DIALOG.MESSAGE'),
644→            onConfirm: (): void =>
645→                this.store.dispatch(PlaylistActions.removeAllPlaylists()),
646→        });
647→    }
648→
649→    private setupSectionObserver(): void {
650→        if (typeof IntersectionObserver === 'undefined') {
651→            return;
652→        }
653→
654→        const scrollRoot = this.getScrollRoot();
655→        const contentSections = Array.from(
656→            this.elementRef.nativeElement.querySelectorAll(
657→                '.settings-group[id]'
658→            )
659→        ) as HTMLElement[];
660→        const sections: ObservedSettingsSection[] = contentSections.map(
661→            (section) => ({
662→                id: section.id,
663→                element: section,
664→            })
665→        );
666→
667→        if (sections.length === 0) {
668→            return;
669→        }
670→
671→        this.sectionObserver?.disconnect();
672→        this.sectionObserver = new IntersectionObserver(
673→            () => {
674→                const activeSection = this.resolveActiveSection(sections);
675→                if (activeSection) {
676→                    this.settingsCtx.setActiveSection(activeSection);
677→                }
678→            },
679→            {
680→                root: scrollRoot,
681→                threshold: [0.12, 0.24, 0.4, 0.6],
682→                rootMargin: '-18% 0px -52% 0px',
683→            }
684→        );
685→
686→        sections.forEach((section) =>
687→            this.sectionObserver?.observe(section.element)
688→        );
689→
690→        const initialSection = this.resolveActiveSection(sections);
691→        if (initialSection) {
692→            this.settingsCtx.setActiveSection(initialSection);
693→        }
694→    }
695→
696→    private resolveActiveSection(
697→        sections: ObservedSettingsSection[]
698→    ): string | null {
699→        const scrollRoot = this.getScrollRoot();
700→        const rootTop = scrollRoot?.getBoundingClientRect().top ?? 0;
701→        const rootHeight = scrollRoot?.clientHeight ?? window.innerHeight;
702→        const activationLine = rootTop + Math.min(rootHeight * 0.28, 220);
703→        const sectionAtActivationLine = sections.find((section) => {
704→            const rect = section.element.getBoundingClientRect();
705→            return rect.top <= activationLine && rect.bottom >= activationLine;
706→        });
707→
708→        if (sectionAtActivationLine) {
709→            return sectionAtActivationLine.id;
710→        }
711→
712→        const nearestSection = sections
713→            .map((section) => ({
714→                id: section.id,
715→                distance: Math.abs(
716→                    section.element.getBoundingClientRect().top - activationLine
717→                ),
718→            }))
719→            .sort((a, b) => a.distance - b.distance)[0];
720→
721→        return nearestSection?.id ?? null;
722→    }
723→
724→    private getScrollRoot(): HTMLElement | null {
725→        return this.elementRef.nativeElement.closest(
726→            'main.workspace-content'
727→        ) as HTMLElement | null;
728→    }
729→}
