            background: var(--mat-sys-surface-container);
        }

        &.is-active {
            color: var(--app-selection-color);
            background: linear-gradient(
                145deg,
                var(--app-selection-surface-strong),
                var(--app-selection-surface)
            );
            box-shadow:
                inset 0 0 0 1px var(--app-selection-border),
                0 10px 20px -16px var(--app-selection-glow);
        }
    }
}

.header-shortcut--global {
    position: relative;

    &::before {
        content: '';
        position: absolute;
        bottom: 5px;
        right: 5px;
        width: 7px;
        height: 7px;
        border-radius: 50%;
        background: var(--mat-sys-tertiary);
        border: 1.5px solid
            var(--app-header-bg, var(--mat-sys-surface-container-low));
        z-index: 1;
    }
}

.header-actions-divider {
    width: 1px;
    height: 20px;
    background: var(--mat-sys-outline-variant);
    margin: 0 4px;
    flex-shrink: 0;
    opacity: 0.6;
}

@media (max-width: 960px) {
    .search-field {
        min-width: 120px;
        flex: 1 1 150px;

        .search-chip {
            max-width: 150px;
        }
    }
}

@media (max-width: 780px) {
    .workspace-header {
        padding-inline: 10px;
        gap: 10px;
    }

    .playlist-switcher {
        width: 190px;
    }

    .header-actions {
        gap: 0;
    }

    .search-field {
        gap: 6px;
        padding-inline: 10px;

        .search-chip {
            max-width: 116px;
            padding-inline: 8px;
        }
    }
}

@media (max-width: 640px) {
    .playlist-switcher {
        width: auto;
        min-width: 140px;
        flex: 1;
    }

    .search-field {
        .search-chip--status {
            display: none;
        }
    }
}

