148→    /** Filtered playlists based on search query, sorted by importDate (newest first) */
149→    readonly filteredPlaylists = computed(() => {
150→        const query = this.searchQuery().toLowerCase().trim();
151→        const filters = this.playlistTypeFilters();
152→        const allPlaylists = this.playlists();
153→        const filteredByType = allPlaylists.filter((playlist) => {
154→            const playlistType = this.getPlaylistFilterType(playlist);
155→            return filters[playlistType];
156→        });
157→        const filtered = query
158→            ? filteredByType.filter(
159→                  (p) =>
160→                      p.title?.toLowerCase().includes(query) ||
161→                      p.filename?.toLowerCase().includes(query)
162→              )
163→            : filteredByType;
164→
165→        return [...filtered].sort(
166→            (a, b) =>
167→                new Date(b.importDate ?? 0).getTime() -
168→                new Date(a.importDate ?? 0).getTime()
169→        );
170→    });
