209→    constructor() {
210→        // Extract playlist ID from current route
211→        this.updateActivePlaylistFromRoute(this.router.url);
212→        this.rememberSectionFromRoute(this.router.url);
213→        effect(() => {
214→            if (!this.allPlaylistsLoaded()) {
215→                return;
216→            }
217→            const playlistIds = this.playlists().map(
218→                (playlist) => playlist._id
219→            );
220→            this.removeDeletedPlaylistsFromSectionMemory(playlistIds);
221→        });
222→        effect(() => {
223→            const allPlaylistsLoaded = this.allPlaylistsLoaded();
224→            const playlistIds = this.playlists().map(
225→                (playlist) => playlist._id
226→            );
227→            const playlistIdSet = new Set(playlistIds);
228→            const selectedId = this.selectedPlaylistId();
229→            const routeId = this.routePlaylistId();
230→            const storedId = this.readPersistedActivePlaylistId();
231→
232→            // Before playlists are loaded, avoid stale cleanups.
233→            // But still keep storage in sync with explicit runtime context.
234→            if (!allPlaylistsLoaded) {
235→                if (routeId) {
236→                    this.writePersistedActivePlaylistId(routeId);
237→                    return;
238→                }
239→                if (selectedId) {
240→                    this.writePersistedActivePlaylistId(selectedId);
241→                }
242→                return;
243→            }
244→
245→            // If route provides playlist context, keep storage in sync with URL state.
246→            if (routeId && playlistIdSet.has(routeId)) {
247→                this.writePersistedActivePlaylistId(routeId);
248→                return;
249→            }
250→
251→            // Keep storage up-to-date with selected playlist state.
252→            if (selectedId && playlistIdSet.has(selectedId)) {
253→                this.writePersistedActivePlaylistId(selectedId);
254→                return;
255→            }
256→
257→            // On routes without playlist in URL (for example dashboard),
258→            // restore last known active playlist when store has none.
259→            if (
260→                !routeId &&
261→                !selectedId &&
262→                storedId &&
263→                playlistIdSet.has(storedId)
264→            ) {
265→                this.store.dispatch(
266→                    PlaylistActions.setActivePlaylist({ playlistId: storedId })
267→                );
268→                return;
269→            }
270→
271→            // Remove stale value if playlist no longer exists.
272→            if (storedId && !playlistIdSet.has(storedId)) {
273→                this.clearPersistedActivePlaylistId();
274→            }
275→        });
276→
277→        // Listen for route changes
278→        this.router.events
279→            .pipe(
280→                filter((event) => event instanceof NavigationEnd),
281→                takeUntilDestroyed()
282→            )
283→            .subscribe((event: NavigationEnd) => {
284→                this.updateActivePlaylistFromRoute(event.urlAfterRedirects);
285→                this.rememberSectionFromRoute(event.urlAfterRedirects);
286→            });
287→
288→        this.destroyRef.onDestroy(() => {
289→            this.clearMenuOverlayWidth();
290→            this.clearSearchFocusTimeout();
291→        });
292→    }
