294→    private updateActivePlaylistFromRoute(url: string) {
295→        // Match routes like /playlists/:id, /xtreams/:id, /stalker/:id
296→        const match = url.match(/\/(playlists|xtreams|stalker)\/([^/?]+)/);
297→        if (match) {
298→            this.routePlaylistId.set(match[2]);
299→        } else {
300→            this.routePlaylistId.set(null);
301→        }
302→    }
303→
304→    private rememberSectionFromRoute(url: string): void {
305→        const routeContext = this.getRouteContext(url);
306→        if (!routeContext.provider || !routeContext.section) {
307→            return;
308→        }
309→
310→        const normalized = this.normalizeSectionForProvider(
311→            routeContext.section,
312→            routeContext.provider
313→        );
314→        if (!normalized) {
315→            return;
316→        }
317→
318→        const memory = this.readSectionMemory();
319→        memory.providers[routeContext.provider] = normalized;
320→        if (routeContext.playlistId) {
321→            memory.playlists[routeContext.playlistId] = {
322→                provider: routeContext.provider,
323→                section: normalized,
324→                updatedAt: Date.now(),
325→            };
326→        }
327→        this.writeSectionMemory(memory);
328→    }
