330→    private async checkPortalStatuses(playlists: PlaylistMeta[]) {
331→        const statusPromises = playlists
332→            .filter(
333→                (playlist) =>
334→                    playlist.serverUrl && playlist.username && playlist.password
335→            )
336→            .map(async (playlist) => {
337→                try {
338→                    const status =
339→                        await this.portalStatusService.checkPortalStatus(
340→                            playlist.serverUrl,
341→                            playlist.username,
342→                            playlist.password
343→                        );
344→                    return { id: playlist._id, status };
345→                } catch {
346→                    return {
347→                        id: playlist._id,
348→                        status: 'unavailable' as PortalStatus,
349→                    };
350→                }
351→            });
352→
353→        const results = await Promise.all(statusPromises);
354→        const statusMap = new Map(results.map((r) => [r.id, r.status]));
355→        this.portalStatuses.set(statusMap);
356→    }
