480→    private getRouteContext(url: string): PlaylistRouteContext {
481→        const inWorkspace = this.isWorkspaceRoute(url);
482→        const isWorkspaceDashboard =
483→            /^\/workspace(?:\/dashboard)?(?:\/)?(?:\?.*)?$/.test(url);
484→        const match = url.match(
485→            /^\/(?:workspace\/)?(playlists|xtreams|stalker)\/([^/?]+)(?:\/([^/?]+))?/
486→        );
487→
488→        return {
489→            inWorkspace,
490→            isWorkspaceDashboard,
491→            provider: (match?.[1] as PlaylistRouteProvider | undefined) ?? null,
492→            playlistId: match?.[2] ?? null,
493→            section: match?.[3] ?? null,
494→        };
495→    }
496→
497→    private getTargetCommands(
498→        provider: PlaylistRouteProvider,
499→        playlistId: string,
500→        routeContext: PlaylistRouteContext
501→    ): string[] | null {
502→        const prefix = routeContext.inWorkspace ? ['workspace'] : [];
503→
504→        // In workspace routes without explicit provider context (for example
505→        // dashboard and sources), selecting a source should only change active
506→        // context and must not trigger navigation.
507→        if (routeContext.inWorkspace && !routeContext.provider) {
508→            return null;
509→        }
510→
511→        if (provider === 'playlists') {
512→            const section = this.resolveTargetSection(
513→                provider,
514→                routeContext.section,
515→                playlistId
516→            );
517→            return [...prefix, 'playlists', playlistId, section];
518→        }
519→
520→        if (!this.supportsSectionNavigation(provider)) {
521→            return [...prefix, provider, playlistId];
522→        }
523→
524→        const section = this.resolveTargetSection(
525→            provider,
526→            routeContext.section,
527→            playlistId
528→        );
529→        return [...prefix, provider, playlistId, section];
530→    }
531→
532→    private resolveTargetSection(
533→        provider: PlaylistSectionProvider,
534→        currentSection: string | null,
535→        targetPlaylistId: string
536→    ): string {
537→        const fromCurrent = this.normalizeSectionForProvider(
538→            currentSection,
539→            provider
540→        );
541→        if (fromCurrent) {
542→            return fromCurrent;
543→        }
544→
545→        const memory = this.readSectionMemory();
546→        const playlistMemory = memory.playlists[targetPlaylistId];
547→        if (playlistMemory?.provider === provider) {
548→            const normalizedPlaylistSection = this.normalizeSectionForProvider(
549→                playlistMemory.section,
550→                provider
551→            );
552→            if (normalizedPlaylistSection) {
553→                return normalizedPlaylistSection;
554→            }
555→        }
556→
557→        const providerMemory = memory.providers[provider];
558→        const normalizedProviderSection = this.normalizeSectionForProvider(
559→            providerMemory,
560→            provider
561→        );
562→        if (normalizedProviderSection) {
563→            return normalizedProviderSection;
564→        }
565→
566→        if (provider === 'playlists') {
567→            return 'all';
568→        }
569→
570→        return 'vod';
571→    }
572→
573→    private supportsSectionNavigation(
574→        provider: PlaylistSectionProvider
575→    ): boolean {
576→        if (provider === 'xtreams') {
577→            return Boolean(window.electron);
578→        }
579→        return true;
580→    }
581→
582→    private normalizeSectionForProvider(
583→        section: string | null | undefined,
584→        provider: PlaylistSectionProvider
585→    ): string | null {
586→        if (!section) {
587→            return null;
588→        }
589→
590→        if (provider === 'xtreams') {
591→            if (section === 'itv') {
592→                return 'live';
593→            }
594→            return XTREAM_SECTIONS.includes(
595→                section as (typeof XTREAM_SECTIONS)[number]
596→            )
597→                ? section
598→                : null;
599→        }
600→
601→        if (provider === 'playlists') {
602→            return M3U_SECTIONS.includes(
603→                section as (typeof M3U_SECTIONS)[number]
604→            )
605→                ? section
606→                : null;
607→        }
608→
609→        if (section === 'live') {
610→            return 'itv';
611→        }
612→        if (section === 'recently-added') {
613→            return 'recent';
614→        }
615→        return STALKER_SECTIONS.includes(
616→            section as (typeof STALKER_SECTIONS)[number]
617→        )
618→            ? section
619→            : null;
620→    }
621→
622→    private readSectionMemory(): PlaylistSectionMemory {
623→        const empty: PlaylistSectionMemory = { providers: {}, playlists: {} };
624→
625→        try {
626→            const raw = localStorage.getItem(LAST_SECTION_STORAGE_KEY);
627→            if (!raw) {
628→                return empty;
629→            }
630→            const parsed = JSON.parse(raw);
631→            if (typeof parsed !== 'object' || parsed === null) {
632→                return empty;
633→            }
634→
635→            const providers: Partial<Record<PlaylistSectionProvider, string>> =
636→                {};
637→            const playlists: PlaylistSectionMemory['playlists'] = {};
638→
639→            const parsedProviders = (parsed as Record<string, unknown>)[
640→                'providers'
641→            ];
642→            if (
643→                typeof parsedProviders === 'object' &&
644→                parsedProviders !== null
645→            ) {
646→                const candidate = parsedProviders as Record<string, unknown>;
647→                if (typeof candidate['playlists'] === 'string') {
648→                    providers.playlists = candidate['playlists'];
649→                }
650→                if (typeof candidate['xtreams'] === 'string') {
651→                    providers.xtreams = candidate['xtreams'];
652→                }
653→                if (typeof candidate['stalker'] === 'string') {
654→                    providers.stalker = candidate['stalker'];
655→                }
656→            } else {
657→                // Backward compatibility with previous format:
658→                // { playlists: "...", xtreams: "...", stalker: "..." }
659→                const legacy = parsed as Record<string, unknown>;
660→                if (typeof legacy['playlists'] === 'string') {
661→                    providers.playlists = legacy['playlists'];
662→                }
663→                if (typeof legacy['xtreams'] === 'string') {
664→                    providers.xtreams = legacy['xtreams'];
665→                }
666→                if (typeof legacy['stalker'] === 'string') {
667→                    providers.stalker = legacy['stalker'];
668→                }
669→            }
670→
671→            const parsedPlaylists = (parsed as Record<string, unknown>)[
672→                'playlists'
673→            ];
674→            if (
675→                typeof parsedPlaylists === 'object' &&
676→                parsedPlaylists !== null
677→            ) {
678→                Object.entries(
679→                    parsedPlaylists as Record<string, unknown>
680→                ).forEach(([playlistId, value]) => {
681→                    if (!value || typeof value !== 'object' || !playlistId) {
682→                        return;
683→                    }
684→
685→                    const row = value as Record<string, unknown>;
686→                    const provider = row['provider'];
687→                    const section = row['section'];
688→                    const updatedAt = row['updatedAt'];
689→                    const isProviderValid =
690→                        provider === 'playlists' ||
691→                        provider === 'xtreams' ||
692→                        provider === 'stalker';
693→                    if (!isProviderValid || typeof section !== 'string') {
694→                        return;
695→                    }
696→
697→                    playlists[playlistId] = {
698→                        provider,
699→                        section,
700→                        updatedAt:
701→                            typeof updatedAt === 'number'
702→                                ? updatedAt
703→                                : Date.now(),
704→                    };
705→                });
706→            }
707→
708→            return { providers, playlists };
709→        } catch {
710→            return empty;
711→        }
712→    }
