807→    private removeDeletedPlaylistsFromSectionMemory(
808→        existingIds: string[]
809→    ): void {
810→        const existingIdSet = new Set(existingIds);
811→        const memory = this.readSectionMemory();
812→        const currentEntries = Object.entries(memory.playlists);
813→        if (currentEntries.length === 0) {
814→            return;
815→        }
816→
817→        const nextPlaylists: PlaylistSectionMemory['playlists'] = {};
818→        let hasChanges = false;
819→
820→        currentEntries.forEach(([playlistId, entry]) => {
821→            if (!existingIdSet.has(playlistId)) {
822→                hasChanges = true;
823→                return;
824→            }
825→
826→            const normalizedSection = this.normalizeSectionForProvider(
827→                entry.section,
828→                entry.provider
829→            );
830→            if (!normalizedSection) {
