@use 'sass:map';
@use '@angular/material' as mat;
@use 'styles';

@include mat.elevation-classes();
@include mat.app-background();

// ─── Typography ─────────────────────────────────────────────────────────────
$my-typography: mat.m2-define-typography-config(
    $font-family: "'DM Sans', 'Inter', sans-serif",
);
@include mat.typography-hierarchy($my-typography);

// ─── M3 Themes ───────────────────────────────────────────────────────────────
$light-theme: mat.define-theme(
    (
        color: (
            theme-type: light,
            primary: mat.$violet-palette,
            tertiary: mat.$cyan-palette,
        ),
        typography: (
            plain-family: "'DM Sans', 'Inter', sans-serif",
            brand-family: "'DM Sans', 'Inter', sans-serif",
        ),
    )
);

$dark-theme: mat.define-theme(
    (
        color: (
            theme-type: dark,
            primary: mat.$violet-palette,
            tertiary: mat.$cyan-palette,
        ),
        typography: (
            plain-family: "'DM Sans', 'Inter', sans-serif",
            brand-family: "'DM Sans', 'Inter', sans-serif",
        ),
    )
);

// ─── Apply Themes ────────────────────────────────────────────────────────────
html {
    @include mat.all-component-themes($light-theme);

    // ── Light theme design tokens ─────────────────────────────────────────
    --app-shell-bg: #eef0f3;
    --app-rail-bg: #eef0f3;
    --app-header-bg: #eef0f3;
    --app-content-bg: #f5f6f8;
    --app-rail-border: transparent;
    --app-on-surface: #1d1b1e;
    --app-hover-overlay: rgba(0, 0, 0, 0.06);
    --app-search-bg: rgba(255, 255, 255, 0.7);
    --app-search-border: rgba(0, 0, 0, 0.1);
    --app-selection-color: #2f7bff;
    --app-selection-on-color: #eef4ff;
    --app-selection-surface: color-mix(
        in srgb,
        var(--app-selection-color) 14%,
        transparent
    );
    --app-selection-surface-strong: color-mix(
        in srgb,
        var(--app-selection-color) 22%,
        transparent
    );
    --app-selection-border: color-mix(
        in srgb,
        var(--app-selection-color) 52%,
        transparent
    );
    --app-selection-glow: color-mix(
        in srgb,
        var(--app-selection-color) 34%,
        transparent
    );

    // Content area
    --app-content-shadow: -2px 4px 12px rgba(0, 0, 0, 0.06);

    // Widget surfaces — no borders, layered backgrounds
    --app-widget-bg: #ffffff;
    --app-widget-header-bg: #fafbfc;
    --app-widget-border: transparent;
    --app-widget-shadow: 0 1px 3px rgba(0, 0, 0, 0.06), 0 4px 12px rgba(0, 0, 0, 0.04);
    --app-widget-header-border: rgba(0, 0, 0, 0.06);
    --app-card-hover-bg: #f0f2f5;
    --app-separator: rgba(0, 0, 0, 0.14);

    // Typography — subdued, not pure black
    --app-heading-color: #1a1d23;
    --app-body-color: #4a5060;
    --app-muted-color: #8891a4;
    --app-eyebrow-color: #7c8495;

    // Provider accent colors
    --app-provider-xtream: #6366f1;
    --app-provider-stalker: #10b981;
    --app-provider-m3u: #d97706;

    // Hero
    --app-accent-gradient: linear-gradient(
        135deg,
        rgba(99, 102, 241, 0.08) 0%,
        rgba(168, 85, 247, 0.05) 100%
    );
    --app-hero-surface: rgba(99, 102, 241, 0.04);

    .dark-theme {
        @include mat.all-component-colors($dark-theme);

        // ── Dark graphite theme ────────────────────────────────────────────
        // Inspired by both Slack (sidebar distinction) and GitButler (data density)
        // Key principle: clearly distinct surface layers using graphite steps
        // Darkest → lightest: #0d0f12 → #141720 → #1c2030 → #222840

        // App shell & navigation
        --app-shell-bg: #0d0f12;
        --app-rail-bg: #111318;
        --app-header-bg: #111318;
        --app-content-bg: #161a22;
        --app-rail-border: transparent;
        --app-search-bg: rgba(255, 255, 255, 0.05);
        --app-search-border: rgba(255, 255, 255, 0.09);
        --app-selection-color: #78adff;
        --app-selection-on-color: #071225;
        --app-selection-surface: color-mix(
            in srgb,
            var(--app-selection-color) 18%,
            transparent
        );
        --app-selection-surface-strong: color-mix(
            in srgb,
            var(--app-selection-color) 28%,
            transparent
        );
        --app-selection-border: color-mix(
            in srgb,
            var(--app-selection-color) 62%,
            transparent
        );
        --app-selection-glow: color-mix(
            in srgb,
            var(--app-selection-color) 44%,
            transparent
        );

        // Content area
        --app-content-shadow: -4px 8px 20px rgba(0, 0, 0, 0.18);

        // Widget surfaces — NO border, surface contrast does the work
        // Widgets sit on content-bg (#161a22), so widget-bg is notably lighter
        --app-widget-bg: #1e2330;
        --app-widget-header-bg: #232840;
        --app-widget-border: transparent;
        --app-widget-shadow: none;
        --app-widget-header-border: rgba(255, 255, 255, 0.05);
        --app-card-hover-bg: #252b3a;
        --app-separator: rgba(255, 255, 255, 0.14);

        // Typography — NOT pure white. Warm graphite-tinted whites
        --app-heading-color: #d8dce8;       // soft off-white, not #fff
        --app-body-color: #8b93a8;          // muted blue-grey
        --app-muted-color: #5c6478;         // dimmed
        --app-eyebrow-color: #6b7494;       // eyebrow labels

        // Provider accents (slightly brighter for dark bg)
        --app-provider-xtream: #818cf8;
        --app-provider-stalker: #34d399;
        --app-provider-m3u: #fbbf24;

        // Hero section
        --app-accent-gradient: linear-gradient(
            135deg,
            rgba(99, 102, 241, 0.12) 0%,
            rgba(168, 85, 247, 0.07) 100%
        );
        --app-hero-surface: rgba(30, 35, 48, 0.9);
    }
}

:host {
    display: block;
    min-width: 0;
    min-height: 0;
}

.app-rail {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    height: 100%;
    box-sizing: border-box;
    padding: 10px 8px;
    border-right: 1px solid
        var(--app-rail-border, var(--mat-sys-outline-variant));
    background: var(--app-rail-bg, var(--mat-sys-surface-container-low));
    app-region: drag;
    overflow-y: auto;
    overflow-x: hidden;
    scrollbar-width: none;
    --rail-link-color: var(--mat-sys-on-surface-variant);
    --rail-link-hover-color: var(--mat-sys-on-surface);
    --rail-link-hover-bg: color-mix(
        in srgb,
        var(--mat-sys-on-surface) 8%,
        transparent
    );
    --rail-link-active-bg: var(--app-selection-surface);
    --rail-link-active-bg-strong: var(--app-selection-surface-strong);
    --rail-link-active-color: var(--app-selection-color);
    --rail-link-active-icon: var(--app-selection-color);
    --rail-link-active-border: var(--app-selection-border);
    --rail-link-active-glow: var(--app-selection-glow);

    &.is-macos {
        padding-top: 36px;
    }

    &::-webkit-scrollbar {
        display: none;
    }
}

.app-rail a {
    width: 44px;
    height: 44px;
    border-radius: 14px;
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--rail-link-color);
    text-decoration: none;
    transition:
        background-color 0.2s ease,
        color 0.2s ease,
        box-shadow 0.2s ease,
        transform 0.2s ease;
    app-region: no-drag;

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
    }
}

.app-rail a:hover {
    color: var(--rail-link-hover-color);
    background: var(--rail-link-hover-bg);
}

.app-rail a.is-active,
.app-rail a.active {
    color: var(--rail-link-active-color);
    background: linear-gradient(
        145deg,
        var(--rail-link-active-bg-strong),
        var(--rail-link-active-bg)
    );
    box-shadow:
        inset 0 0 0 1px var(--rail-link-active-border),
        0 10px 20px -16px var(--rail-link-active-glow);
    transform: translateY(-1px);

    mat-icon {
        color: var(--rail-link-active-icon);
    }

    &::after {
        content: '';
        position: absolute;
        right: -4px;
        top: 50%;
        transform: translateY(-50%);
        width: 3px;
        height: 18px;
        border-radius: 999px;
        background: var(--rail-link-active-icon);
        box-shadow: 0 0 10px var(--rail-link-active-glow);
    }
}

.brand {
    margin-bottom: 10px;
    background: var(--mat-sys-primary-container);
    color: var(--mat-sys-on-primary-container);
    width: 40px;
    height: 40px;
    border-radius: 12px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.brand img {
    width: 24px;
    height: 24px;
    object-fit: contain;
}

.rail-context-region {
    --region-accent: var(--mat-sys-outline-variant);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    width: 100%;
    max-width: 48px;
    padding: 5px 2px;
    margin: 4px 0;
    border-radius: 14px;
    background: color-mix(in srgb, var(--mat-sys-on-surface) 3%, transparent);
    border: 1px solid color-mix(in srgb, var(--mat-sys-on-surface) 4%, transparent);
    position: relative;
    animation: region-enter 0.25s ease-out both;

    &::before {
        content: '';
        position: absolute;
        top: -1px;
        left: 10px;
        right: 10px;
        height: 2px;
        border-radius: 0 0 2px 2px;
        background: var(--region-accent);
        opacity: 0.5;
    }

    .rail-divider {
        width: 24px;
        margin: 3px 0;
        opacity: 0.25;
    }
}

.rail-context-region--xtreams {
    --region-accent: #7c8cf5;
}

.rail-context-region--stalker {
    --region-accent: #4ecdc4;
}

.rail-context-region--playlists {
    --region-accent: #f5a623;
}

@keyframes region-enter {
    from {
        opacity: 0;
        transform: scale(0.95);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

.rail-divider {
    width: 44px;
    height: 1px;
    background: var(--mat-sys-outline-variant);
    margin: 6px 0;
    opacity: 0.5;
}

.rail-footer {
    margin-top: auto;

    .rail-shortcut {
        width: 44px;
        height: 44px;
        padding: 0;
        gap: 0;
        border-radius: 14px;
        position: relative;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        color: var(--mat-sys-on-surface-variant);
        app-region: no-drag;

        mat-icon {
            font-size: 20px;
            width: 20px;
            height: 20px;
        }

        &:hover:not(.is-active) {
            background: color-mix(
                in srgb,
                var(--mat-sys-on-surface) 8%,
                transparent
            );
            color: var(--mat-sys-on-surface);
        }

        &.is-active::after {
            content: '';
            position: absolute;
            right: -4px;
            top: 50%;
            transform: translateY(-50%);
            width: 4px;
            height: 20px;
            border-radius: 999px;
            background: var(--app-selection-color);
            box-shadow: 0 0 10px var(--app-selection-glow);
        }
    }
}

@media (max-width: 640px) {
    .app-rail {
        flex-direction: row;
        justify-content: space-between;
        padding: 6px 10px;
        border-right: none;
        border-bottom: 1px solid var(--mat-sys-outline-variant);

        .brand {
            margin-bottom: 0;
        }
    }

    .rail-divider {
        width: 1px;
        height: 24px;
        margin: 0 4px;
    }

    .rail-context-region {
        width: auto;
        flex-direction: row;
        margin: 0;
        padding: 2px 4px;
        border-radius: 10px;

        &::before {
            display: none;
        }

        .rail-divider {
            width: 1px;
            height: 24px;
            margin: 0 2px;
        }
    }

    .rail-footer {
        margin-top: 0;
    }
}

