        filter: drop-shadow(0 0 4px var(--epg-accent-glow));
    }

    50% {
        filter: drop-shadow(0 0 10px var(--epg-accent-glow));
    }
}

.imports-list {
    max-height: 360px;
    overflow-y: auto;
    padding: 4px 0;

    &::-webkit-scrollbar {
        width: 6px;
    }

    &::-webkit-scrollbar-track {
        background: var(--epg-scrollbar-track);
        border-radius: 3px;
        margin: 4px 0;
    }

    &::-webkit-scrollbar-thumb {
        background: var(--epg-scrollbar-thumb);
        border-radius: 3px;

        &:hover {
            background: var(--epg-accent);
        }
    }
}

.import-item {
    padding: 6px 12px;
    border-radius: 10px;
    transition: all 0.2s ease;
    position: relative;
    margin: 0 6px;

    &:not(:last-child) {
        margin-bottom: 2px;
    }

    &:hover {
        background: var(--epg-item-hover);
    }

    .item-header {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 10px;

        .status-icon-wrapper {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 32px;
            height: 32px;
            border-radius: 8px;
            background: var(--epg-icon-bg);
            flex-shrink: 0;
        }

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
            transition: all 0.3s ease;
        }

        .item-url {
            flex: 1;
            font-size: 12px;
            font-weight: 500;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            color: var(--epg-text-secondary);
            font-family: 'SF Mono', 'Fira Code', 'Monaco', monospace;
            letter-spacing: -0.02em;
        }

        .dismiss-btn {
            width: 26px;
            height: 26px;
            padding: 2px;
            line-height: 26px;
            border-radius: 6px;
            opacity: 0;
            transition: all 0.2s ease;
            color: var(--epg-text-tertiary);

            mat-icon {
                font-size: 16px;
                width: 16px;
                height: 16px;
            }
        }
    }

    &:hover .dismiss-btn {
        opacity: 1;
    }

    &.status-loading {
        .status-icon-wrapper mat-icon {
            color: var(--epg-accent);
        }
    }

    &.status-complete {
        .status-icon-wrapper mat-icon {
            color: var(--epg-success);
            filter: drop-shadow(0 0 6px var(--epg-success-glow));
        }
    }

    &.status-error {
        .status-icon-wrapper mat-icon {
            color: var(--epg-error);
            filter: drop-shadow(0 0 6px var(--epg-error-glow));
        }
    }
}

.spinning {
    animation: spin 1.2s linear infinite;
}

@keyframes spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

.item-stats {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-left: 42px;
    min-height: 24px;

    .stat-badge {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        padding: 4px 8px;
        border-radius: 999px;
        font-size: 11px;
        font-weight: 500;
        background: var(--epg-item-border);
        color: var(--epg-text-secondary);

        mat-icon {
            font-size: 14px;
            width: 14px;
            height: 14px;
        }
    }

    .error-text {
        font-size: 12px;
        color: var(--epg-error);
    }
}

.queue-section {
    margin: 8px 6px 6px;
    padding: 10px 12px;
    border-radius: 12px;
    background: var(--epg-queue-bg);
    border: 1px solid var(--epg-queue-border);
}

.queue-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
    font-size: 12px;
    font-weight: 600;
    color: var(--epg-text-primary);

    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
        color: var(--epg-queued);
    }
}

.queue-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.queue-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 6px 8px;
    border-radius: 8px;
    color: var(--epg-text-secondary);

    .queue-position {
        width: 18px;
        text-align: center;
        font-size: 11px;
        font-weight: 700;
        color: var(--epg-queued);
    }

    .queue-url {
        flex: 1;
        font-size: 12px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        font-family: 'SF Mono', 'Fira Code', 'Monaco', monospace;
    }

    .dismiss-btn {
        width: 24px;
        height: 24px;
        padding: 2px;
        line-height: 24px;
        color: var(--epg-text-tertiary);
    }
}

@media (max-width: 700px) {
    .epg-progress-panel {
        left: 12px;
        right: 12px;
        bottom: 12px;
        width: auto;
        max-width: none;
    }
}

