 22→    DownloadsService,
 23→    PlaylistsService,
 24→} from 'services';
 25→import { queryParamSignal } from '@iptvnator/portal/shared/util';
 26→import { createPortalCollectionContext } from '@iptvnator/portal/shared/util';
 27→import {
 28→    buildStandardCollectionCategories,
 29→    filterCollectionBucket,
 30→} from '@iptvnator/portal/shared/util';
 31→import { PortalCollectionContextService } from '@iptvnator/portal/shared/util';
 32→import { Playlist } from 'shared-interfaces';
 33→
 34→type PortalSource = 'xtream' | 'stalker';
 35→const DOWNLOAD_COLLECTION_LABELS = {
 36→    all: 'All',
 37→    movie: 'Movies',
 38→    live: 'Live TV',
 39→    series: 'Series',
 40→};
 41→
 42→@Component({
 43→    selector: 'app-downloads',
 44→    templateUrl: './downloads.component.html',
 45→    styleUrls: [
 46→        './downloads.component.scss',
 47→        '../../../../shared/ui/src/lib/styles/portal-sidebar.scss',
 48→    ],
 49→    changeDetection: ChangeDetectionStrategy.OnPush,
 50→    imports: [
 51→        MatButtonModule,
 52→        MatIcon,
 53→        MatProgressBarModule,
 54→        MatTooltip,
 55→        TranslatePipe,
 56→    ],
 57→})
 58→export class DownloadsComponent {
 59→    private readonly route = inject(ActivatedRoute);
 60→    private readonly router = inject(Router);
 61→    private readonly dbService = inject(DatabaseService);
 62→    private readonly playlistsService = inject(PlaylistsService);
 63→    private readonly collectionCtx = inject(PortalCollectionContextService);
 64→    private readonly dialogService = inject(DialogService);
 65→    private readonly translate = inject(TranslateService);
 66→    private readonly snackBar = inject(MatSnackBar);
 67→    readonly downloadsService = inject(DownloadsService);
 68→
 69→    readonly downloads = this.downloadsService.downloads;
 70→    readonly downloadFolder = this.downloadsService.downloadFolder;
 71→    readonly isAvailable = this.downloadsService.isAvailable;
 72→    readonly hasDownloads = this.downloadsService.hasDownloads;
 73→    readonly activeCount = this.downloadsService.activeCount;
 74→    readonly playlistId = toSignal(
 75→        this.route.paramMap.pipe(map((params) => params.get('id') ?? '')),
 76→        { initialValue: this.route.snapshot.params['id'] ?? '' }
 77→    );
 78→    readonly searchTerm = queryParamSignal(this.route, 'q', (value) =>
 79→        (value ?? '').trim().toLowerCase()
 80→    );
 81→    readonly playlists = toSignal(this.playlistsService.getAllPlaylists(), {
 82→        initialValue: [] as Playlist[],
 83→    });
 84→
 85→    readonly scopedDownloads = computed(() => {
 86→        const playlistId = this.playlistId();
 87→        const downloads = this.downloads();
 88→        return playlistId
 89→            ? downloads.filter((item) => item.playlistId === playlistId)
 90→            : downloads;
 91→    });
 92→
 93→    readonly categories = computed(() => {
 94→        const downloads = this.scopedDownloads();
 95→        const moviesCount = downloads.filter(
 96→            (item) => item.contentType === 'vod'
 97→        ).length;
 98→        const seriesCount = downloads.filter(
 99→            (item) => item.contentType === 'episode'
100→        ).length;
101→
102→        return buildStandardCollectionCategories({
103→            labels: DOWNLOAD_COLLECTION_LABELS,
104→            counts: {
105→                all: downloads.length,
106→                movie: moviesCount,
107→                series: seriesCount,
108→            },
109→        });
110→    });
111→    readonly collectionContext = createPortalCollectionContext({
112→        ctx: this.collectionCtx,
113→        categories: this.categories,
114→    });
115→    readonly selectedCategoryId = this.collectionContext.selectedCategoryId;
116→    readonly failedPosterKeys = signal<Record<string, true>>({});
117→
118→    /** Filter downloads for current playlist and sort by newest first */
119→    readonly filteredDownloads = computed(() => {
120→        const term = this.searchTerm();
121→        const downloads = this.scopedDownloads();
122→        const filteredByTerm = filterCollectionBucket({
123→            selectedCategoryId: this.selectedCategoryId(),
124→            allItems: downloads,
125→            buckets: {
126→                movie: downloads.filter((item) => item.contentType === 'vod'),
127→                series: downloads.filter(
128→                    (item) => item.contentType === 'episode'
129→                ),
130→            },
131→            searchTerm: term,
132→            textOf: (item) => `${item.title ?? ''} ${item.errorMessage ?? ''}`,
133→        });
134→
135→        // Sort by createdAt descending (newest first)
136→        return [...filteredByTerm].sort((a, b) => {
137→            const dateA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
138→            const dateB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
139→            return dateB - dateA;
140→        });
141→    });
142→    readonly hasClearableDownloads = computed(() =>
143→        this.scopedDownloads().some(
144→            (item) =>
145→                item.status === 'completed' ||
146→                item.status === 'failed' ||
147→                item.status === 'canceled'
148→        )
149→    );
150→    readonly availablePlaylistIds = computed(
151→        () => new Set(this.playlists().map((playlist) => playlist._id))
152→    );
153→
154→    constructor() {
155→        effect(() => {
156→            const playlistId = this.playlistId();
157→            this.collectionContext.setCategoryId('all');
158→            void this.downloadsService.loadDownloads(playlistId || undefined);
159→        });
160→    }
161→
162→    getProgress(item: DownloadItem): number {
163→        return this.downloadsService.getProgressPercent(item);
164→    }
165→
166→    formatBytes(bytes: number | undefined): string {
167→        if (!bytes) return '0 B';
168→        return this.downloadsService.formatBytes(bytes);
169→    }
170→
171→    getStatusIcon(status: string): string {
172→        switch (status) {
173→            case 'queued':
174→                return 'schedule';
175→            case 'downloading':
176→                return 'downloading';
177→            case 'completed':
178→                return 'check_circle';
179→            case 'failed':
180→                return 'error';
181→            case 'canceled':
182→                return 'cancel';
183→            default:
184→                return 'help';
185→        }
186→    }
187→
188→    getStatusColor(status: string): string {
189→        switch (status) {
190→            case 'queued':
191→                return 'status-queued';
192→            case 'downloading':
193→                return 'status-downloading';
194→            case 'completed':
195→                return 'status-completed';
196→            case 'failed':
197→            case 'canceled':
198→                return 'status-failed';
199→            default:
200→                return '';
201→        }
202→    }
203→
204→    async cancel(item: DownloadItem) {
205→        await this.downloadsService.cancelDownload(item.id);
206→    }
207→
208→    async retry(item: DownloadItem) {
209→        await this.downloadsService.retryDownload(item.id);
210→    }
211→
212→    async remove(item: DownloadItem) {
213→        await this.downloadsService.removeDownload(item.id);
214→    }
215→
216→    async play(item: DownloadItem) {
217→        if (item.filePath) {
218→            const result = await this.downloadsService.playDownload(
219→                item.filePath
220→            );
221→            if (!result.success) {
222→                this.handleFileActionError(result.error);
223→            }
224→        }
225→    }
226→
227→    async reveal(item: DownloadItem) {
228→        if (item.filePath) {
229→            const result = await this.downloadsService.revealFile(item.filePath);
230→            if (!result.success) {
231→                this.handleFileActionError(result.error);
232→            }
233→        }
234→    }
235→
236→    async changeFolder() {
237→        await this.downloadsService.selectFolder();
238→    }
239→
240→    async clearCompleted() {
241→        this.dialogService.openConfirmDialog({
242→            title: this.translate.instant(
243→                'DOWNLOADS.CLEAR_COMPLETED_DIALOG.TITLE'
244→            ),
245→            message: this.translate.instant(
246→                'DOWNLOADS.CLEAR_COMPLETED_DIALOG.MESSAGE'
247→            ),
248→            confirmLabel: this.translate.instant('DOWNLOADS.CLEAR_COMPLETED'),
249→            onConfirm: async (): Promise<void> => {
250→                await this.downloadsService.clearCompleted(this.playlistId());
251→            },
252→        });
253→    }
254→
255→    formatEpisodeLabel(item: DownloadItem): string {
256→        if (item.contentType !== 'episode') return '';
257→        const s = item.seasonNumber?.toString().padStart(2, '0') || '00';
258→        const e = item.episodeNumber?.toString().padStart(2, '0') || '00';
259→        return `S${s}E${e}`;
260→    }
261→
262→    hasPoster(item: DownloadItem): boolean {
263→        return !!item.posterUrl && !this.failedPosterKeys()[this.getPosterKey(item)];
264→    }
265→
266→    markPosterFailed(item: DownloadItem): void {
267→        const key = this.getPosterKey(item);
268→        this.failedPosterKeys.update((state) => {
269→            if (state[key]) {
270→                return state;
271→            }
272→
273→            return {
274→                ...state,
275→                [key]: true,
276→            };
277→        });
278→    }
279→
280→    getPosterPlaceholderIcon(item: DownloadItem): string {
281→        return item.contentType === 'episode' ? 'video_library' : 'movie';
282→    }
283→
284→    hasSourcePlaylist(item: DownloadItem): boolean {
285→        return this.availablePlaylistIds().has(item.playlistId);
286→    }
287→
288→    isItemNavigable(item: DownloadItem): boolean {
289→        return (
290→            !!item.playlistId &&
291→            this.hasSourcePlaylist(item) &&
292→            this.getTargetContentId(item) !== null
293→        );
294→    }
295→
296→    onItemCardKeydown(event: KeyboardEvent, item: DownloadItem): void {
297→        if (event.target !== event.currentTarget) {
298→            return;
299→        }
300→
301→        if (event.key !== 'Enter' && event.key !== ' ') {
302→            return;
303→        }
304→
305→        event.preventDefault();
306→        void this.openInLibrary(item);
307→    }
308→
309→    async openInLibrary(item: DownloadItem): Promise<void> {
310→        if (!this.hasSourcePlaylist(item)) {
311→            this.snackBar.open(
312→                this.translate.instant('DOWNLOADS.SOURCE_PLAYLIST_MISSING'),
313→                undefined,
314→                { duration: 3000, horizontalPosition: 'start' }
315→            );
316→            return;
317→        }
318→
319→        if (!this.isItemNavigable(item)) {
320→            return;
321→        }
322→
323→        const source = await this.resolveSourceType(item.playlistId);
324→        if (!source) {
325→            return;
326→        }
327→
328→        if (source === 'xtream') {
329→            await this.openXtreamItem(item);
330→            return;
331→        }
332→
333→        await this.openStalkerItem(item);
334→    }
335→
336→    private getTargetContentId(item: DownloadItem): number | null {
337→        const id =
338→            item.contentType === 'episode'
339→                ? (item.seriesXtreamId ?? item.xtreamId)
340→                : item.xtreamId;
341→        const numeric = Number(id);
342→        return Number.isFinite(numeric) ? numeric : null;
343→    }
344→
345→    private buildPlaylistRoute(
346→        source: PortalSource,
347→        playlistId: string,
348→        segments: Array<string | number>
349→    ): Array<string | number> {
350→        const sourceSegment = source === 'stalker' ? 'stalker' : 'xtreams';
351→        return ['/workspace', sourceSegment, playlistId, ...segments];
352→    }
353→
354→    private async resolveSourceType(
355→        playlistId: string
356→    ): Promise<PortalSource | null> {
357→        try {
358→            const playlist = await firstValueFrom(
359→                this.playlistsService.getPlaylistById(playlistId)
360→            );
361→
362→            if (!playlist) {
363→                return null;
364→            }
365→
366→            if (playlist.portalUrl && playlist.macAddress) {
367→                return 'stalker';
368→            }
369→
370→            return 'xtream';
371→        } catch {
372→            return null;
373→        }
374→    }
375→
376→    private async openXtreamItem(item: DownloadItem): Promise<void> {
377→        const targetId = this.getTargetContentId(item);
378→        if (targetId === null) return;
379→
380→        const contentType = item.contentType === 'episode' ? 'series' : 'vod';
381→        const content = await this.dbService.getContentByXtreamId(
382→            targetId,
383→            item.playlistId
384→        );
385→        const categoryId = content?.category_id;
386→
387→        if (categoryId === null || categoryId === undefined) {
388→            await this.router.navigate(
389→                this.buildPlaylistRoute('xtream', item.playlistId, [
390→                    contentType,
391→                ])
392→            );
393→            return;
394→        }
395→
396→        await this.router.navigate(
397→            this.buildPlaylistRoute('xtream', item.playlistId, [
398→                contentType,
399→                String(categoryId),
400→                String(targetId),
401→            ])
402→        );
403→    }
404→
405→    private normalizePortalItemId(value: unknown): string {
406→        const raw = String(value ?? '').trim();
407→        if (!raw) return '';
408→        return raw.includes(':') ? raw.split(':')[0] : raw;
409→    }
410→
411→    private normalizeStalkerCategoryId(
412→        value: unknown,
413→        fallback: 'vod' | 'series'
414→    ): 'vod' | 'series' | 'itv' {
415→        const normalized = String(value ?? '').toLowerCase();
416→        if (normalized === 'movie') return 'vod';
417→        if (
418→            normalized === 'vod' ||
419→            normalized === 'series' ||
420→            normalized === 'itv'
421→        ) {
422→            return normalized;
423→        }
424→        return fallback;
425→    }
426→
427→    private findMatchingStalkerRecentItem(
428→        items: Array<Record<string, unknown>>,
429→        targetId: number
430→    ): Record<string, unknown> | undefined {
431→        const expectedId = String(targetId);
432→        return items.find((recentItem) => {
433→            const candidates = [
434→                recentItem['id'],
435→                recentItem['movie_id'],
436→                recentItem['series_id'],
437→                recentItem['stream_id'],
438→            ];
439→
440→            return candidates.some(
441→                (candidate) =>
442→                    this.normalizePortalItemId(candidate) === expectedId
443→            );
444→        });
445→    }
446→
447→    private async buildStalkerOpenState(
448→        item: DownloadItem,
449→        targetId: number,
450→        fallbackCategory: 'vod' | 'series'
451→    ): Promise<Record<string, unknown>> {
452→        try {
453→            const items = (await firstValueFrom(
454→                this.playlistsService.getPortalRecentlyViewed(item.playlistId)
455→            )) as Array<Record<string, unknown>>;
456→
457→            const matched = this.findMatchingStalkerRecentItem(items, targetId);
458→
459→            if (matched) {
460→                return {
461→                    ...matched,
462→                    id:
463→                        matched['id'] ??
464→                        matched['series_id'] ??
465→                        matched['movie_id'] ??
466→                        String(targetId),
467→                    category_id: this.normalizeStalkerCategoryId(
468→                        matched['category_id'],
469→                        fallbackCategory
470→                    ),
471→                    title: matched['title'] ?? item.title,
472→                    name: matched['name'] ?? matched['o_name'] ?? item.title,
473→                };
474→            }
475→        } catch {
476→            // Ignore and use fallback state below.
477→        }
478→
479→        return {
480→            id: String(targetId),
481→            category_id: fallbackCategory,
482→            title: item.title,
483→            name: item.title,
484→            o_name: item.title,
485→            cover: item.posterUrl,
486→            logo: item.posterUrl,
487→        };
488→    }
489→
490→    private async openStalkerItem(item: DownloadItem): Promise<void> {
491→        const targetId = this.getTargetContentId(item);
492→        if (targetId === null) return;
493→
494→        const fallbackCategory =
495→            item.contentType === 'episode' ? 'series' : 'vod';
496→        const openRecentItem = await this.buildStalkerOpenState(
497→            item,
498→            targetId,
499→            fallbackCategory
500→        );
501→
502→        await this.router.navigate(
503→            this.buildPlaylistRoute('stalker', item.playlistId, ['recent']),
504→            {
505→                state: { openRecentItem },
506→            }
507→        );
508→    }
509→
510→    private getPosterKey(item: DownloadItem): string {
511→        return `${item.id}:${item.posterUrl ?? ''}`;
512→    }
513→
514→    private handleFileActionError(error?: string): void {
515→        const message =
516→            error === 'File not found'
517→                ? this.translate.instant('DOWNLOADS.FILE_NOT_FOUND')
518→                : this.translate.instant('DOWNLOADS.FILE_ACTION_ERROR');
519→
520→        this.snackBar.open(message, undefined, {
521→            duration: 3000,
522→            horizontalPosition: 'start',
523→        });
524→    }
525→}
