  3→
  4→export type DownloadStatus =
  5→    | 'queued'
  6→    | 'downloading'
  7→    | 'completed'
  8→    | 'failed'
  9→    | 'canceled';
 10→
 11→export interface DownloadItem {
 12→    id: number;
 13→    playlistId: string;
 14→    xtreamId: number;
 15→    contentType: 'vod' | 'episode';
 16→    seriesXtreamId?: number;
 17→    seasonNumber?: number;
 18→    episodeNumber?: number;
 19→    title: string;
 20→    url: string;
 21→    fileName?: string;
 22→    filePath?: string;
 23→    posterUrl?: string;
 24→    status: DownloadStatus;
