 32→@Injectable({ providedIn: 'root' })
 33→export class DownloadsService implements OnDestroy {
 34→    private readonly settingsStore = inject(SettingsStore);
 35→    private unsubscribe?: () => void;
 36→
 37→    /** Signal for the list of downloads */
 38→    readonly downloads = signal<DownloadItem[]>([]);
 39→
 40→    /** Whether the download feature is available (Electron only) */
 41→    readonly isAvailable = computed(() => !!window.electron?.downloadsGetList);
 42→
 43→    /** Whether there are any downloads */
 44→    readonly hasDownloads = computed(() => this.downloads().length > 0);
 45→
 46→    /** Active downloads count */
 47→    readonly activeCount = computed(
 48→        () =>
 49→            this.downloads().filter(
 50→                (d) => d.status === 'queued' || d.status === 'downloading'
 51→            ).length
 52→    );
 53→
 54→    /** Completed downloads count */
 55→    readonly completedCount = computed(
 56→        () => this.downloads().filter((d) => d.status === 'completed').length
 57→    );
 58→
 59→    /** Failed downloads count */
 60→    readonly failedCount = computed(
 61→        () =>
 62→            this.downloads().filter(
 63→                (d) => d.status === 'failed' || d.status === 'canceled'
 64→            ).length
 65→    );
 66→
 67→    /** Current download folder */
 68→    readonly downloadFolder = signal<string>('');
 69→
 70→    constructor() {
 71→        this.init();
 72→    }
 73→
 74→    private async init() {
 75→        if (!this.isAvailable()) {
 76→            return;
 77→        }
 78→
 79→        // Load initial download list
 80→        await this.loadDownloads();
 81→
 82→        // Load download folder
 83→        await this.loadDownloadFolder();
 84→
 85→        // Subscribe to download updates
 86→        this.unsubscribe = window.electron.onDownloadsUpdate(() => {
 87→            this.loadDownloads();
 88→        });
 89→    }
 90→
 91→    ngOnDestroy() {
 92→        this.unsubscribe?.();
 93→    }
 94→
 95→    /**
 96→     * Load downloads from the backend
 97→     */
 98→    async loadDownloads(playlistId?: string): Promise<void> {
 99→        if (!this.isAvailable()) return;
100→
101→        try {
102→            const list = await window.electron.downloadsGetList(playlistId);
103→            this.downloads.set(list);
