301→    /**
302→     * Select a new download folder
303→     */
304→    async selectFolder(): Promise<string | null> {
305→        if (!this.isAvailable()) {
306→            return null;
307→        }
308→
309→        try {
310→            const folder = await window.electron.downloadsSelectFolder();
311→            if (folder) {
