346→
347→    /**
348→     * Get download progress as percentage
349→     */
350→    getProgressPercent(item: DownloadItem): number {
351→        if (!item.totalBytes || item.totalBytes === 0) {
352→            return 0;
353→        }
354→        return Math.round(
355→            ((item.bytesDownloaded || 0) / item.totalBytes) * 100
356→        );
357→    }
358→
359→    /**
360→     * Get download item by xtreamId and playlistId
361→     */
362→    getDownloadByContent(
363→        xtreamId: number,
364→        playlistId: string,
365→        contentType: 'vod' | 'episode'
366→    ): DownloadItem | undefined {
367→        return this.downloads().find(
368→            (d) =>
369→                d.xtreamId === xtreamId &&
370→                d.playlistId === playlistId &&
371→                d.contentType === contentType
372→        );
373→    }
374→
375→    /**
376→     * Check if content is downloaded (completed status)
377→     */
378→    isDownloaded(
379→        xtreamId: number,
380→        playlistId: string,
381→        contentType: 'vod' | 'episode'
382→    ): boolean {
383→        const download = this.getDownloadByContent(xtreamId, playlistId, contentType);
384→        return download?.status === 'completed' && !!download.filePath;
385→    }
386→
387→    /**
388→     * Check if content is currently downloading or queued
389→     */
390→    isDownloading(
391→        xtreamId: number,
392→        playlistId: string,
393→        contentType: 'vod' | 'episode'
394→    ): boolean {
395→        const download = this.getDownloadByContent(xtreamId, playlistId, contentType);
396→        return download?.status === 'downloading' || download?.status === 'queued';
397→    }
398→
399→    /**
400→     * Get the file path for a downloaded content item
401→     */
402→    getDownloadedFilePath(
403→        xtreamId: number,
404→        playlistId: string,
405→        contentType: 'vod' | 'episode'
406→    ): string | undefined {
407→        const download = this.getDownloadByContent(xtreamId, playlistId, contentType);
408→        if (download?.status === 'completed') {
409→            return download.filePath;
410→        }
411→        return undefined;
412→    }
413→
414→    /**
415→     * Format bytes to human readable string
416→     */
417→    formatBytes(bytes: number): string {
418→        if (bytes === 0) return '0 B';
419→        const k = 1024;
420→        const sizes = ['B', 'KB', 'MB', 'GB'];
421→        const i = Math.floor(Math.log(bytes) / Math.log(k));
422→        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
423→    }
424→}
