  1→/**
  2→ * Downloads IPC event handlers
  3→ * Uses electron-dl for download management with queue control and progress tracking
  4→ */
  5→
  6→import { and, eq, inArray, sql } from 'drizzle-orm';
  7→import { app, BrowserWindow, dialog, ipcMain, shell } from 'electron';
  8→import { download, File as ElectronDlFile } from 'electron-dl';
  9→import { existsSync, unlinkSync } from 'fs';
 10→import { basename, extname, join } from 'path';
 11→import { getDatabase } from '../../database/connection';
 12→import * as schema from '../../database/schema';
 13→
 14→type DownloadStatus = 'queued' | 'downloading' | 'completed' | 'failed' | 'canceled';
 15→
 16→interface DownloadTask {
 17→    id: number;
 18→    url: string;
 19→    fileName: string;
 20→    directory: string;
 21→    headers?: Record<string, string>;
 22→    downloadItem?: ElectronDlFile;
 23→}
 24→
 25→// Download queue management
 26→const downloadQueue: DownloadTask[] = [];
 27→let activeDownload: DownloadTask | null = null;
 28→let mainWindow: BrowserWindow | null = null;
 29→
 30→/**
 31→ * Set the main window reference for sending updates
 32→ */
 33→export function setMainWindow(win: BrowserWindow) {
 34→    mainWindow = win;
 35→}
 36→
 37→/**
 38→ * Broadcast download updates to renderer
 39→ */
 40→function broadcastUpdate() {
 41→    if (mainWindow && !mainWindow.isDestroyed()) {
 42→        mainWindow.webContents.send('DOWNLOADS_UPDATE_EVENT');
 43→    }
 44→}
 45→
 46→/**
 47→ * Get file extension from URL
 48→ */
 49→function getExtensionFromUrl(url: string): string {
 50→    try {
 51→        const urlObj = new URL(url);
 52→        const pathname = urlObj.pathname;
 53→        const ext = extname(pathname);
 54→        return ext || '.mp4';
 55→    } catch {
 56→        return '.mp4';
 57→    }
 58→}
 59→
 60→/**
 61→ * Sanitize filename for filesystem
 62→ */
 63→function sanitizeFilename(name: string): string {
 64→    return name.replace(/[<>:"/\\|?*]/g, '_').trim();
 65→}
 66→
 67→/**
 68→ * Process the download queue - starts next download if none active
 69→ */
 70→async function processQueue() {
 71→    if (activeDownload || downloadQueue.length === 0) {
 72→        return;
 73→    }
 74→
 75→    const task = downloadQueue.shift();
 76→    if (!task) return;
 77→
 78→    activeDownload = task;
 79→    await startDownload(task);
 80→}
 81→
 82→/**
 83→ * Start a download using electron-dl
 84→ */
 85→async function startDownload(task: DownloadTask) {
 86→    const db = await getDatabase();
 87→
 88→    // Update status to downloading
 89→    await db
 90→        .update(schema.downloads)
 91→        .set({
 92→            status: 'downloading',
 93→            updatedAt: sql`CURRENT_TIMESTAMP`,
 94→        })
 95→        .where(eq(schema.downloads.id, task.id));
 96→
 97→    broadcastUpdate();
 98→
 99→    if (!mainWindow || mainWindow.isDestroyed()) {
100→        console.error('[Downloads] No main window available');
101→        await db
102→            .update(schema.downloads)
103→            .set({
104→                status: 'failed',
105→                errorMessage: 'No window available for download',
106→                updatedAt: sql`CURRENT_TIMESTAMP`,
107→            })
108→            .where(eq(schema.downloads.id, task.id));
109→        activeDownload = null;
110→        broadcastUpdate();
111→        processQueue();
112→        return;
113→    }
114→
115→    let lastProgressUpdate = 0;
116→    const PROGRESS_THROTTLE_MS = 500;
117→
118→    try {
119→        const downloadOptions: Parameters<typeof download>[2] = {
120→            directory: task.directory,
121→            filename: task.fileName,
122→            overwrite: true,
123→            onStarted: (item) => {
124→                console.log(`[Downloads] Started: ${task.fileName}`);
125→                task.downloadItem = item as unknown as ElectronDlFile;
126→            },
127→            onProgress: async (progress) => {
128→                const now = Date.now();
129→                if (now - lastProgressUpdate < PROGRESS_THROTTLE_MS) {
130→                    return;
131→                }
132→                lastProgressUpdate = now;
133→
134→                await db
135→                    .update(schema.downloads)
136→                    .set({
137→                        bytesDownloaded: progress.transferredBytes,
138→                        totalBytes: progress.totalBytes,
139→                        updatedAt: sql`CURRENT_TIMESTAMP`,
140→                    })
141→                    .where(eq(schema.downloads.id, task.id));
142→
143→                broadcastUpdate();
144→            },
145→            onCompleted: async (file) => {
146→                console.log(`[Downloads] Completed: ${task.fileName}`);
147→                await db
148→                    .update(schema.downloads)
149→                    .set({
150→                        status: 'completed',
151→                        filePath: file.path,
152→                        fileName: file.filename,
153→                        bytesDownloaded: file.fileSize,
154→                        totalBytes: file.fileSize,
155→                        updatedAt: sql`CURRENT_TIMESTAMP`,
156→                    })
157→                    .where(eq(schema.downloads.id, task.id));
158→
159→                activeDownload = null;
160→                broadcastUpdate();
161→                processQueue();
162→            },
163→            onCancel: async () => {
164→                console.log(`[Downloads] Canceled: ${task.fileName}`);
165→                // Delete partial file if it exists
166→                const partialPath = join(task.directory, task.fileName);
167→                if (existsSync(partialPath)) {
168→                    try {
169→                        unlinkSync(partialPath);
170→                    } catch (e) {
171→                        console.error('[Downloads] Failed to delete partial file:', e);
172→                    }
173→                }
174→
175→                await db
176→                    .update(schema.downloads)
177→                    .set({
178→                        status: 'canceled',
179→                        updatedAt: sql`CURRENT_TIMESTAMP`,
180→                    })
181→                    .where(eq(schema.downloads.id, task.id));
182→
183→                activeDownload = null;
184→                broadcastUpdate();
185→                processQueue();
186→            },
187→        };
188→
189→        // Add headers if provided (user-agent, referer, origin)
190→        if (task.headers) {
191→            (downloadOptions as any).headers = task.headers;
192→        }
193→
194→        await download(mainWindow, task.url, downloadOptions);
195→    } catch (error) {
196→        console.error(`[Downloads] Error downloading ${task.fileName}:`, error);
197→
198→        // Delete partial file if it exists
199→        const partialPath = join(task.directory, task.fileName);
200→        if (existsSync(partialPath)) {
201→            try {
202→                unlinkSync(partialPath);
203→            } catch (e) {
204→                console.error('[Downloads] Failed to delete partial file:', e);
205→            }
206→        }
207→
208→        await db
209→            .update(schema.downloads)
210→            .set({
211→                status: 'failed',
212→                errorMessage: error instanceof Error ? error.message : String(error),
213→                updatedAt: sql`CURRENT_TIMESTAMP`,
214→            })
215→            .where(eq(schema.downloads.id, task.id));
216→
217→        activeDownload = null;
218→        broadcastUpdate();
219→        processQueue();
220→    }
221→}
