223→/**
224→ * Enqueue a new download
225→ */
226→ipcMain.handle(
227→    'DOWNLOADS_START',
228→    async (
229→        _event,
230→        data: {
231→            playlistId: string;
232→            xtreamId: number;
233→            contentType: 'vod' | 'episode';
234→            title: string;
235→            url: string;
236→            posterUrl?: string;
237→            downloadFolder: string;
238→            headers?: { userAgent?: string; referer?: string; origin?: string };
239→            seriesXtreamId?: number;
240→            seasonNumber?: number;
241→            episodeNumber?: number;
242→            // Playlist info for auto-creation if needed
243→            playlistName?: string;
244→            playlistType?: 'xtream' | 'stalker' | 'm3u-file' | 'm3u-text' | 'm3u-url';
245→            serverUrl?: string;
246→            portalUrl?: string;
247→            macAddress?: string;
248→        }
249→    ) => {
250→        try {
251→            console.log('[Downloads] Enqueue download:', data.title);
252→            const db = await getDatabase();
253→
254→            // Ensure playlist exists in database (required for foreign key constraint)
255→            if (data.playlistId) {
256→                const existingPlaylist = await db
257→                    .select()
258→                    .from(schema.playlists)
259→                    .where(eq(schema.playlists.id, data.playlistId))
260→                    .limit(1);
261→
262→                if (existingPlaylist.length === 0) {
263→                    // Create playlist entry for downloads to work
264→                    console.log('[Downloads] Creating playlist entry for:', data.playlistId);
265→                    await db.insert(schema.playlists).values({
266→                        id: data.playlistId,
267→                        name: data.playlistName || 'Unknown Playlist',
268→                        type: data.playlistType || 'stalker',
269→                        serverUrl: data.serverUrl,
270→                        macAddress: data.macAddress,
271→                        url: data.portalUrl,
272→                    });
273→                }
274→            } else {
275→                throw new Error('playlistId is required for downloads');
276→            }
277→
278→            // Check if already exists
279→            const existing = await db
280→                .select()
281→                .from(schema.downloads)
282→                .where(
283→                    and(
284→                        eq(schema.downloads.playlistId, data.playlistId),
285→                        eq(schema.downloads.xtreamId, data.xtreamId),
286→                        eq(schema.downloads.contentType, data.contentType)
287→                    )
288→                )
289→                .limit(1);
290→
291→            if (existing.length > 0) {
292→                const item = existing[0];
293→                // If completed or failed/canceled, allow retry by updating
294→                if (['completed', 'failed', 'canceled'].includes(item.status)) {
295→                    await db
296→                        .update(schema.downloads)
297→                        .set({
298→                            status: 'queued',
299→                            url: data.url,
300→                            bytesDownloaded: 0,
301→                            totalBytes: null,
302→                            errorMessage: null,
303→                            updatedAt: sql`CURRENT_TIMESTAMP`,
304→                        })
305→                        .where(eq(schema.downloads.id, item.id));
306→
307→                    const ext = getExtensionFromUrl(data.url);
308→                    const fileName = sanitizeFilename(data.title) + ext;
309→
310→                    downloadQueue.push({
311→                        id: item.id,
312→                        url: data.url,
313→                        fileName,
314→                        directory: data.downloadFolder,
315→                        headers: data.headers
316→                            ? {
317→                                  'User-Agent': data.headers.userAgent || '',
318→                                  Referer: data.headers.referer || '',
319→                                  Origin: data.headers.origin || '',
320→                              }
321→                            : undefined,
322→                    });
323→
324→                    broadcastUpdate();
325→                    processQueue();
326→                    return { success: true, id: item.id };
327→                }
328→
329→                // Already queued or downloading
330→                return { success: false, error: 'Download already in progress', id: item.id };
331→            }
332→
333→            // Create new download entry
334→            const ext = getExtensionFromUrl(data.url);
335→            const fileName = sanitizeFilename(data.title) + ext;
336→
337→            const result = await db.insert(schema.downloads).values({
338→                playlistId: data.playlistId,
339→                xtreamId: data.xtreamId,
340→                contentType: data.contentType,
341→                title: data.title,
342→                url: data.url,
343→                posterUrl: data.posterUrl,
344→                fileName,
345→                status: 'queued',
346→                seriesXtreamId: data.seriesXtreamId,
347→                seasonNumber: data.seasonNumber,
348→                episodeNumber: data.episodeNumber,
349→            });
350→
351→            const insertedId = Number(result.lastInsertRowid);
352→
353→            downloadQueue.push({
354→                id: insertedId,
355→                url: data.url,
356→                fileName,
357→                directory: data.downloadFolder,
358→                headers: data.headers
359→                    ? {
360→                          'User-Agent': data.headers.userAgent || '',
361→                          Referer: data.headers.referer || '',
362→                          Origin: data.headers.origin || '',
363→                      }
364→                    : undefined,
365→            });
366→
367→            broadcastUpdate();
368→            processQueue();
369→
370→            return { success: true, id: insertedId };
371→        } catch (error) {
372→            console.error('[Downloads] Error enqueuing download:', error);
373→            throw error;
374→        }
375→    }
376→);
