378→/**
379→ * Cancel a download
380→ */
381→ipcMain.handle('DOWNLOADS_CANCEL', async (_event, downloadId: number) => {
382→    try {
383→        console.log('[Downloads] Cancel download:', downloadId);
384→        const db = await getDatabase();
385→
386→        // Check if it's the active download
387→        if (activeDownload && activeDownload.id === downloadId) {
388→            if (activeDownload.downloadItem) {
389→                (activeDownload.downloadItem as any).cancel?.();
390→            }
391→            return { success: true };
392→        }
393→
394→        // Remove from queue
395→        const queueIndex = downloadQueue.findIndex((t) => t.id === downloadId);
396→        if (queueIndex !== -1) {
397→            downloadQueue.splice(queueIndex, 1);
398→            await db
399→                .update(schema.downloads)
400→                .set({
401→                    status: 'canceled',
402→                    updatedAt: sql`CURRENT_TIMESTAMP`,
403→                })
404→                .where(eq(schema.downloads.id, downloadId));
405→
406→            broadcastUpdate();
407→            return { success: true };
408→        }
409→
410→        return { success: false, error: 'Download not found in queue' };
411→    } catch (error) {
412→        console.error('[Downloads] Error canceling download:', error);
413→        throw error;
414→    }
415→});
