431→                .limit(1);
432→
433→            if (existing.length === 0) {
434→                return { success: false, error: 'Download not found' };
435→            }
436→
437→            const item = existing[0];
438→            if (!['failed', 'canceled'].includes(item.status)) {
439→                return { success: false, error: 'Can only retry failed or canceled downloads' };
440→            }
441→
442→            await db
443→                .update(schema.downloads)
444→                .set({
445→                    status: 'queued',
446→                    bytesDownloaded: 0,
447→                    totalBytes: null,
448→                    errorMessage: null,
449→                    updatedAt: sql`CURRENT_TIMESTAMP`,
450→                })
451→                .where(eq(schema.downloads.id, downloadId));
452→
453→            const ext = getExtensionFromUrl(item.url);
454→            const fileName = sanitizeFilename(item.title) + ext;
455→
456→            downloadQueue.push({
457→                id: item.id,
458→                url: item.url,
459→                fileName,
460→                directory: downloadFolder,
461→            });
462→
463→            broadcastUpdate();
464→            processQueue();
465→
466→            return { success: true };
467→        } catch (error) {
468→            console.error('[Downloads] Error retrying download:', error);
469→            throw error;
470→        }
471→    }
472→);
