474→/**
475→ * Remove a download from the list
476→ */
477→ipcMain.handle('DOWNLOADS_REMOVE', async (_event, downloadId: number) => {
478→    try {
479→        console.log('[Downloads] Remove download:', downloadId);
480→        const db = await getDatabase();
481→
482→        // Cancel if active
