  1→import { HttpClient } from '@angular/common/http';
  2→import { inject, Injectable } from '@angular/core';
  3→import { StorageMap } from '@ngx-pwa/local-storage';
  4→import { catchError, map, Observable } from 'rxjs';
  5→import { STORE_KEY, Theme } from 'shared-interfaces';
  6→
  7→const PRERELEASE_KEYWORDS = [
  8→    'beta',
  9→    'alpha',
 10→    'rc',
 11→    'preview',
 12→    'dev',
 13→    'canary',
 14→    'nightly',
 15→] as const;
 16→
 17→interface ParsedVersion {
 18→    major: number;
 19→    minor: number;
 20→    patch: number;
 21→    prerelease: boolean;
 22→}
 23→
 24→type LegacyMediaQueryList = MediaQueryList & {
 25→    addListener?: (listener: (event: MediaQueryListEvent) => void) => void;
 26→    removeListener?: (listener: (event: MediaQueryListEvent) => void) => void;
 27→};
 28→
 29→function parseVersion(input: string): ParsedVersion | null {
 30→    const normalized = input.trim().replace(/^v/i, '');
 31→    const match = normalized.match(
 32→        /(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:[-+]?([0-9A-Za-z.-]+))?/
 33→    );
 34→
 35→    if (!match) {
 36→        return null;
 37→    }
 38→
 39→    return {
 40→        major: Number(match[1] ?? 0),
 41→        minor: Number(match[2] ?? 0),
 42→        patch: Number(match[3] ?? 0),
 43→        prerelease: Boolean(match[4]),
 44→    };
 45→}
 46→
 47→function hasPrereleaseKeyword(value: string): boolean {
 48→    const normalized = value.toLowerCase();
 49→    return PRERELEASE_KEYWORDS.some((keyword) => normalized.includes(keyword));
 50→}
 51→
 52→function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
 53→    if (a.major !== b.major) {
 54→        return a.major - b.major;
 55→    }
 56→    if (a.minor !== b.minor) {
 57→        return a.minor - b.minor;
 58→    }
 59→    return a.patch - b.patch;
 60→}
