 62→@Injectable({
 63→    providedIn: 'root',
 64→})
 65→export class SettingsService {
 66→    private http = inject(HttpClient);
 67→    private storage = inject(StorageMap);
 68→    private readonly systemThemeMediaQuery =
 69→        typeof window !== 'undefined' && 'matchMedia' in window
 70→            ? window.matchMedia('(prefers-color-scheme: dark)')
 71→            : null;
 72→    private readonly systemThemeChangeHandler = (
 73→        event: MediaQueryListEvent
 74→    ): void => {
 75→        this.applyResolvedTheme(
 76→            event.matches ? Theme.DarkTheme : Theme.LightTheme
 77→        );
 78→    };
 79→    private isSystemThemeSyncActive = false;
 80→
 81→    /**
 82→     * Changes the visual theme of the application
 83→     * @param selectedTheme theme to set
 84→     */
 85→    changeTheme(selectedTheme: Theme): void {
 86→        this.stopSystemThemeSync();
 87→
 88→        if (selectedTheme === Theme.SystemTheme) {
 89→            this.startSystemThemeSync();
 90→            this.applyResolvedTheme(
 91→                this.systemThemeMediaQuery?.matches
 92→                    ? Theme.DarkTheme
 93→                    : Theme.LightTheme
 94→            );
 95→            return;
 96→        }
 97→
 98→        this.applyResolvedTheme(selectedTheme);
 99→    }
100→
101→    private applyResolvedTheme(selectedTheme: Theme): void {
102→        if (selectedTheme === Theme.DarkTheme) {
103→            document.body.classList.add('dark-theme');
104→            return;
105→        }
106→
107→        document.body.classList.remove('dark-theme');
108→    }
109→
110→    private startSystemThemeSync(): void {
111→        if (!this.systemThemeMediaQuery || this.isSystemThemeSyncActive) {
112→            return;
113→        }
114→
115→        const mediaQuery = this.systemThemeMediaQuery as LegacyMediaQueryList;
116→
117→        if (mediaQuery.addEventListener) {
118→            mediaQuery.addEventListener('change', this.systemThemeChangeHandler);
119→        } else {
120→            mediaQuery.addListener?.(this.systemThemeChangeHandler);
121→        }
122→
123→        this.isSystemThemeSyncActive = true;
124→    }
125→
126→    private stopSystemThemeSync(): void {
127→        if (!this.systemThemeMediaQuery || !this.isSystemThemeSyncActive) {
128→            return;
129→        }
130→
131→        const mediaQuery = this.systemThemeMediaQuery as LegacyMediaQueryList;
132→
133→        if (mediaQuery.removeEventListener) {
134→            mediaQuery.removeEventListener(
135→                'change',
136→                this.systemThemeChangeHandler
137→            );
138→        } else {
139→            mediaQuery.removeListener?.(this.systemThemeChangeHandler);
140→        }
141→
142→        this.isSystemThemeSyncActive = false;
143→    }
144→
145→    /**
146→     * Returns the value of the given key from the local storage
147→     * @param key key to get
148→     * @returns returns the value of the given key
149→     */
150→    getValueFromLocalStorage(key: STORE_KEY) {
151→        return this.storage.get(key);
152→    }
153→
154→    /**
155→     * Sets the given key/value pair in the local storage
156→     * @param key key to set
157→     * @param value value to set
158→     * @param withCallback if true, the callback will be called after the value is set
159→     */
160→    setValueToLocalStorage(
161→        key: STORE_KEY,
162→        value: unknown,
163→        withCallback = false
164→    ): Observable<unknown> | void {
165→        if (withCallback) {
166→            return this.storage.set(key, value);
167→        }
168→
169→        this.storage.set(key, value).subscribe();
170→    }
171→
172→    /**
173→     * Returns the version of the released app
174→     * Filters out pre-release versions (beta, alpha, rc)
175→     */
176→    getAppVersion() {
177→        return this.http
178→            .get<{ created_at: string; name: string }[]>(
179→                'https://api.github.com/repos/4gray/iptvnator/releases'
180→            )
181→            .pipe(
182→                map((response) => {
183→                    // Filter out pre-release versions (beta, alpha, rc, etc.)
184→                    const stableReleases = response.filter((release) => {
185→                        if (hasPrereleaseKeyword(release.name)) {
186→                            return false;
187→                        }
188→
189→                        const version = parseVersion(release.name);
190→                        if (!version) return false;
191→
192→                        return !version.prerelease;
193→                    });
194→
195→                    // Sort stable releases by creation date
196→                    const sortedReleases = stableReleases.sort(
197→                        (a, b) =>
198→                            new Date(b.created_at).getTime() -
199→                            new Date(a.created_at).getTime()
200→                    );
201→
202→                    return sortedReleases[0];
203→                }),
204→                map((response) => response.name),
205→                catchError((err) => {
206→                    console.error(err);
207→                    throw new Error(err);
208→                })
209→            );
210→    }
211→
212→    /**
213→     * Compares current version with latest version
214→     * @param currentVersion current version of the app
215→     * @param latestVersion latest stable version from GitHub
216→     * @returns true if current version is outdated
217→     */
218→    isVersionOutdated(
219→        currentVersion: string,
220→        latestVersion: string
221→    ): boolean {
222→        const cleanCurrent = parseVersion(currentVersion);
223→        const cleanLatest = parseVersion(latestVersion);
224→
225→        if (!cleanCurrent || !cleanLatest) {
226→            console.warn('Invalid version format:', {
227→                currentVersion,
228→                latestVersion,
229→            });
230→            return false;
231→        }
232→
233→        return compareVersions(cleanCurrent, cleanLatest) < 0;
234→    }
235→}
