 1→import { Injectable, computed, signal } from '@angular/core';
 2→
 3→export interface EpgImportProgress {
 4→    url: string;
 5→    status: 'queued' | 'loading' | 'complete' | 'error';
 6→    stats?: { totalChannels: number; totalPrograms: number };
 7→    error?: string;
 8→    queuePosition?: number;
 9→}
10→
11→@Injectable({ providedIn: 'root' })
12→export class EpgProgressService {
13→    private readonly importsMap = signal<Map<string, EpgImportProgress>>(
14→        new Map()
15→    );
16→    private initialized = false;
17→
18→    readonly imports = computed(() => Array.from(this.importsMap().values()));
19→    readonly hasActiveImports = computed(() =>
20→        this.imports().some((item) => item.status === 'loading')
21→    );
22→    readonly activeCount = computed(
23→        () => this.imports().filter((item) => item.status === 'loading').length
24→    );
25→    readonly queuedImports = computed(() =>
26→        this.imports()
27→            .filter((item) => item.status === 'queued')
28→            .sort(
29→                (a, b) => (a.queuePosition ?? 0) - (b.queuePosition ?? 0)
30→            )
31→    );
32→    readonly queuedCount = computed(() => this.queuedImports().length);
33→    readonly isVisible = computed(() => this.imports().length > 0);
34→
35→    constructor() {
36→        this.initializeListener();
37→    }
38→
39→    dismiss(url: string): void {
40→        this.removeImport(url);
41→    }
42→
43→    dismissAll(): void {
44→        this.importsMap.set(new Map());
45→    }
46→
47→    private initializeListener(): void {
48→        if (this.initialized) {
49→            return;
50→        }
51→        this.initialized = true;
52→
53→        if (window.electron?.onEpgProgress) {
54→            window.electron.onEpgProgress((data) => {
55→                this.updateProgress(data);
56→            });
57→        }
58→    }
59→
60→    private updateProgress(progress: EpgImportProgress): void {
61→        this.importsMap.update((current) => {
62→            const updated = new Map(current);
63→            updated.set(progress.url, progress);
64→            return updated;
65→        });
66→
67→        if (progress.status === 'complete' || progress.status === 'error') {
68→            setTimeout(() => this.removeImport(progress.url), 5000);
69→        }
70→    }
71→
72→    private removeImport(url: string): void {
73→        this.importsMap.update((current) => {
74→            const updated = new Map(current);
75→            updated.delete(url);
76→            return updated;
77→        });
78→    }
79→}
