 1→import { Component, inject } from '@angular/core';
 2→import { MatButtonModule } from '@angular/material/button';
 3→import { MatIconModule } from '@angular/material/icon';
 4→import { MatProgressBar } from '@angular/material/progress-bar';
 5→import { MatTooltip } from '@angular/material/tooltip';
 6→import { TranslatePipe } from '@ngx-translate/core';
 7→import {
 8→    EpgImportProgress,
 9→    EpgProgressService,
10→} from '@iptvnator/epg/data-access';
11→
12→@Component({
13→    selector: 'app-epg-progress-panel',
14→    standalone: true,
15→    imports: [
16→        MatButtonModule,
17→        MatIconModule,
18→        MatTooltip,
19→        MatProgressBar,
20→        TranslatePipe,
21→    ],
22→    templateUrl: './epg-progress-panel.component.html',
23→    styleUrl: './epg-progress-panel.component.scss',
24→})
25→export class EpgProgressPanelComponent {
26→    private readonly epgProgress = inject(EpgProgressService);
27→
28→    readonly imports = this.epgProgress.imports;
29→    readonly isVisible = this.epgProgress.isVisible;
30→    readonly queuedCount = this.epgProgress.queuedCount;
31→    readonly activeCount = this.epgProgress.activeCount;
32→
33→    get activeImports() {
34→        return this.imports().filter((item) => item.status !== 'queued');
35→    }
36→
37→    get queuedImports() {
38→        return this.imports()
39→            .filter((item) => item.status === 'queued')
40→            .sort(
41→                (a, b) => (a.queuePosition ?? 0) - (b.queuePosition ?? 0)
42→            );
43→    }
44→
45→    getStatusIcon(status: EpgImportProgress['status']): string {
46→        switch (status) {
47→            case 'queued':
48→                return 'schedule';
49→            case 'loading':
50→                return 'sync';
51→            case 'complete':
52→                return 'check_circle';
53→            case 'error':
54→                return 'error';
55→        }
56→    }
57→
58→    getStatusClass(status: EpgImportProgress['status']): string {
59→        return `status-${status}`;
60→    }
61→
62→    getDisplayUrl(url: string): string {
63→        try {
64→            const urlObject = new URL(url);
65→            return urlObject.hostname + urlObject.pathname.split('/').pop();
66→        } catch {
67→            return url.length > 40 ? `${url.substring(0, 40)}...` : url;
68→        }
69→    }
70→
71→    dismiss(url: string): void {
72→        this.epgProgress.dismiss(url);
73→    }
74→
75→    dismissAll(): void {
76→        this.epgProgress.dismissAll();
77→    }
78→}
