  1→import { computed, inject, Injectable, OnDestroy, signal } from '@angular/core';
  2→import { SettingsStore } from './settings-store.service';
  3→
  4→export type DownloadStatus =
  5→    | 'queued'
  6→    | 'downloading'
  7→    | 'completed'
  8→    | 'failed'
  9→    | 'canceled';
 10→
 11→export interface DownloadItem {
 12→    id: number;
 13→    playlistId: string;
 14→    xtreamId: number;
 15→    contentType: 'vod' | 'episode';
 16→    seriesXtreamId?: number;
 17→    seasonNumber?: number;
 18→    episodeNumber?: number;
 19→    title: string;
 20→    url: string;
 21→    fileName?: string;
 22→    filePath?: string;
 23→    posterUrl?: string;
 24→    status: DownloadStatus;
 25→    bytesDownloaded?: number;
 26→    totalBytes?: number;
 27→    errorMessage?: string;
 28→    createdAt?: string;
 29→    updatedAt?: string;
 30→}
 31→
 32→@Injectable({ providedIn: 'root' })
 33→export class DownloadsService implements OnDestroy {
 34→    private readonly settingsStore = inject(SettingsStore);
 35→    private unsubscribe?: () => void;
 36→
 37→    /** Signal for the list of downloads */
 38→    readonly downloads = signal<DownloadItem[]>([]);
 39→
 40→    /** Whether the download feature is available (Electron only) */
 41→    readonly isAvailable = computed(() => !!window.electron?.downloadsGetList);
 42→
 43→    /** Whether there are any downloads */
 44→    readonly hasDownloads = computed(() => this.downloads().length > 0);
 45→
 46→    /** Active downloads count */
 47→    readonly activeCount = computed(
 48→        () =>
 49→            this.downloads().filter(
 50→                (d) => d.status === 'queued' || d.status === 'downloading'
 51→            ).length
 52→    );
 53→
 54→    /** Completed downloads count */
 55→    readonly completedCount = computed(
 56→        () => this.downloads().filter((d) => d.status === 'completed').length
 57→    );
 58→
 59→    /** Failed downloads count */
 60→    readonly failedCount = computed(
 61→        () =>
 62→            this.downloads().filter(
 63→                (d) => d.status === 'failed' || d.status === 'canceled'
 64→            ).length
 65→    );
 66→
 67→    /** Current download folder */
 68→    readonly downloadFolder = signal<string>('');
 69→
 70→    constructor() {
 71→        this.init();
 72→    }
 73→
 74→    private async init() {
 75→        if (!this.isAvailable()) {
 76→            return;
 77→        }
 78→
 79→        // Load initial download list
 80→        await this.loadDownloads();
 81→
 82→        // Load download folder
 83→        await this.loadDownloadFolder();
 84→
 85→        // Subscribe to download updates
 86→        this.unsubscribe = window.electron.onDownloadsUpdate(() => {
 87→            this.loadDownloads();
 88→        });
 89→    }
 90→
 91→    ngOnDestroy() {
 92→        this.unsubscribe?.();
 93→    }
 94→
 95→    /**
 96→     * Load downloads from the backend
 97→     */
 98→    async loadDownloads(playlistId?: string): Promise<void> {
 99→        if (!this.isAvailable()) return;
100→
101→        try {
102→            const list = await window.electron.downloadsGetList(playlistId);
103→            this.downloads.set(list);
104→        } catch (error) {
105→            console.error('[DownloadsService] Error loading downloads:', error);
106→        }
107→    }
108→
109→    /**
110→     * Load or resolve download folder
111→     */
112→    async loadDownloadFolder(): Promise<string> {
113→        if (!this.isAvailable()) return '';
114→
115→        // First check settings
116→        const storedFolder = this.settingsStore.getDownloadFolder?.();
117→        if (storedFolder) {
118→            this.downloadFolder.set(storedFolder);
119→            return storedFolder;
120→        }
121→
122→        // Fall back to default
123→        try {
124→            const defaultFolder =
125→                await window.electron.downloadsGetDefaultFolder();
126→            this.downloadFolder.set(defaultFolder);
127→            return defaultFolder;
128→        } catch (error) {
129→            console.error(
130→                '[DownloadsService] Error getting default folder:',
131→                error
132→            );
133→            return '';
134→        }
135→    }
136→
137→    /**
138→     * Start a new download
139→     */
140→    async startDownload(data: {
141→        playlistId: string;
142→        xtreamId: number;
143→        contentType: 'vod' | 'episode';
144→        title: string;
145→        url: string;
146→        posterUrl?: string;
147→        headers?: { userAgent?: string; referer?: string; origin?: string };
148→        seriesXtreamId?: number;
149→        seasonNumber?: number;
150→        episodeNumber?: number;
151→        // Playlist info for auto-creation if needed (Stalker playlists)
152→        playlistName?: string;
153→        playlistType?: 'xtream' | 'stalker' | 'm3u-file' | 'm3u-text' | 'm3u-url';
154→        serverUrl?: string;
155→        portalUrl?: string;
156→        macAddress?: string;
157→    }): Promise<{ success: boolean; id?: number; error?: string }> {
158→        if (!this.isAvailable()) {
159→            return { success: false, error: 'Downloads not available' };
160→        }
161→
162→        const folder = await this.loadDownloadFolder();
163→        if (!folder) {
164→            return { success: false, error: 'No download folder configured' };
165→        }
166→
167→        try {
168→            const result = await window.electron.downloadsStart({
169→                ...data,
170→                downloadFolder: folder,
171→            });
172→            return result;
173→        } catch (error) {
174→            console.error('[DownloadsService] Error starting download:', error);
175→            return {
176→                success: false,
177→                error: error instanceof Error ? error.message : String(error),
178→            };
179→        }
180→    }
181→
182→    /**
183→     * Cancel a download
184→     */
185→    async cancelDownload(
186→        downloadId: number
187→    ): Promise<{ success: boolean; error?: string }> {
188→        if (!this.isAvailable()) {
189→            return { success: false, error: 'Downloads not available' };
190→        }
191→
192→        try {
193→            return await window.electron.downloadsCancel(downloadId);
194→        } catch (error) {
195→            console.error(
196→                '[DownloadsService] Error canceling download:',
197→                error
198→            );
199→            return {
200→                success: false,
201→                error: error instanceof Error ? error.message : String(error),
202→            };
203→        }
204→    }
205→
206→    /**
207→     * Retry a failed download
208→     */
209→    async retryDownload(
210→        downloadId: number
211→    ): Promise<{ success: boolean; error?: string }> {
212→        if (!this.isAvailable()) {
213→            return { success: false, error: 'Downloads not available' };
214→        }
215→
216→        const folder = await this.loadDownloadFolder();
217→        if (!folder) {
218→            return { success: false, error: 'No download folder configured' };
219→        }
220→
221→        try {
222→            return await window.electron.downloadsRetry(downloadId, folder);
223→        } catch (error) {
224→            console.error(
225→                '[DownloadsService] Error retrying download:',
226→                error
227→            );
228→            return {
229→                success: false,
230→                error: error instanceof Error ? error.message : String(error),
231→            };
232→        }
233→    }
234→
235→    /**
236→     * Remove a download from the list
237→     */
238→    async removeDownload(
239→        downloadId: number
240→    ): Promise<{ success: boolean; error?: string }> {
241→        if (!this.isAvailable()) {
242→            return { success: false, error: 'Downloads not available' };
243→        }
244→
245→        try {
246→            return await window.electron.downloadsRemove(downloadId);
247→        } catch (error) {
248→            console.error(
249→                '[DownloadsService] Error removing download:',
250→                error
251→            );
252→            return {
253→                success: false,
254→                error: error instanceof Error ? error.message : String(error),
255→            };
256→        }
257→    }
258→
259→    /**
260→     * Play a downloaded file
261→     */
262→    async playDownload(
263→        filePath: string
264→    ): Promise<{ success: boolean; error?: string }> {
265→        if (!this.isAvailable()) {
266→            return { success: false, error: 'Downloads not available' };
267→        }
268→
269→        try {
270→            return await window.electron.downloadsPlayFile(filePath);
271→        } catch (error) {
272→            console.error('[DownloadsService] Error playing file:', error);
273→            return {
274→                success: false,
275→                error: error instanceof Error ? error.message : String(error),
276→            };
277→        }
278→    }
279→
280→    /**
281→     * Reveal file in system file manager
282→     */
283→    async revealFile(
284→        filePath: string
285→    ): Promise<{ success: boolean; error?: string }> {
286→        if (!this.isAvailable()) {
287→            return { success: false, error: 'Downloads not available' };
288→        }
289→
290→        try {
291→            return await window.electron.downloadsRevealFile(filePath);
292→        } catch (error) {
293→            console.error('[DownloadsService] Error revealing file:', error);
294→            return {
295→                success: false,
296→                error: error instanceof Error ? error.message : String(error),
297→            };
298→        }
299→    }
300→
301→    /**
302→     * Select a new download folder
303→     */
304→    async selectFolder(): Promise<string | null> {
305→        if (!this.isAvailable()) {
306→            return null;
307→        }
308→
309→        try {
310→            const folder = await window.electron.downloadsSelectFolder();
311→            if (folder) {
312→                this.downloadFolder.set(folder);
313→                // Save to settings
314→                await this.settingsStore.updateSettings({ downloadFolder: folder });
315→            }
316→            return folder;
317→        } catch (error) {
318→            console.error(
319→                '[DownloadsService] Error selecting folder:',
320→                error
321→            );
322→            return null;
323→        }
324→    }
325→
326→    /**
327→     * Clear completed/failed downloads
328→     */
329→    async clearCompleted(
330→        playlistId?: string
331→    ): Promise<{ success: boolean }> {
332→        if (!this.isAvailable()) {
333→            return { success: false };
334→        }
335→
336→        try {
337→            return await window.electron.downloadsClearCompleted(playlistId);
338→        } catch (error) {
339→            console.error(
340→                '[DownloadsService] Error clearing completed:',
341→                error
342→            );
343→            return { success: false };
344→        }
345→    }
346→
347→    /**
348→     * Get download progress as percentage
349→     */
350→    getProgressPercent(item: DownloadItem): number {
351→        if (!item.totalBytes || item.totalBytes === 0) {
352→            return 0;
353→        }
354→        return Math.round(
355→            ((item.bytesDownloaded || 0) / item.totalBytes) * 100
356→        );
357→    }
358→
359→    /**
360→     * Get download item by xtreamId and playlistId
361→     */
362→    getDownloadByContent(
363→        xtreamId: number,
364→        playlistId: string,
365→        contentType: 'vod' | 'episode'
366→    ): DownloadItem | undefined {
367→        return this.downloads().find(
368→            (d) =>
369→                d.xtreamId === xtreamId &&
370→                d.playlistId === playlistId &&
371→                d.contentType === contentType
372→        );
373→    }
374→
375→    /**
376→     * Check if content is downloaded (completed status)
377→     */
378→    isDownloaded(
379→        xtreamId: number,
380→        playlistId: string,
381→        contentType: 'vod' | 'episode'
382→    ): boolean {
383→        const download = this.getDownloadByContent(xtreamId, playlistId, contentType);
384→        return download?.status === 'completed' && !!download.filePath;
385→    }
386→
387→    /**
388→     * Check if content is currently downloading or queued
389→     */
390→    isDownloading(
391→        xtreamId: number,
392→        playlistId: string,
393→        contentType: 'vod' | 'episode'
394→    ): boolean {
395→        const download = this.getDownloadByContent(xtreamId, playlistId, contentType);
396→        return download?.status === 'downloading' || download?.status === 'queued';
397→    }
398→
399→    /**
400→     * Get the file path for a downloaded content item
401→     */
402→    getDownloadedFilePath(
403→        xtreamId: number,
404→        playlistId: string,
405→        contentType: 'vod' | 'episode'
406→    ): string | undefined {
407→        const download = this.getDownloadByContent(xtreamId, playlistId, contentType);
408→        if (download?.status === 'completed') {
409→            return download.filePath;
410→        }
411→        return undefined;
412→    }
413→
414→    /**
415→     * Format bytes to human readable string
416→     */
417→    formatBytes(bytes: number): string {
418→        if (bytes === 0) return '0 B';
419→        const k = 1024;
420→        const sizes = ['B', 'KB', 'MB', 'GB'];
421→        const i = Math.floor(Math.log(bytes) / Math.log(k));
422→        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
423→    }
424→}
