        background: var(--epg-scrollbar-track);
        border-radius: 3px;
        margin: 4px 0;
    }

    &::-webkit-scrollbar-thumb {
        background: var(--epg-scrollbar-thumb);
        border-radius: 3px;

        &:hover {
            background: var(--epg-accent);
        }
    }
}

.import-item {
    padding: 6px 12px;
    border-radius: 10px;
    transition: all 0.2s ease;
    position: relative;
    margin: 0 6px;

    &:not(:last-child) {
        margin-bottom: 2px;
    }

    &:hover {
        background: var(--epg-item-hover);
    }

    .item-header {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 10px;

        .status-icon-wrapper {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 32px;
            height: 32px;
            border-radius: 8px;
            background: var(--epg-icon-bg);
            flex-shrink: 0;
        }

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
            transition: all 0.3s ease;
        }

        .item-url {
            flex: 1;
            font-size: 12px;
            font-weight: 500;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            color: var(--epg-text-secondary);
            font-family: 'SF Mono', 'Fira Code', 'Monaco', monospace;
            letter-spacing: -0.02em;
