    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
        color: var(--epg-queued);
    }
}

.queue-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.queue-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 6px 8px;
    border-radius: 8px;
    color: var(--epg-text-secondary);

    .queue-position {
        width: 18px;
        text-align: center;
        font-size: 11px;
        font-weight: 700;
        color: var(--epg-queued);
    }

    .queue-url {
        flex: 1;
        font-size: 12px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
