:host {
    // Theme-aware tokens — map to app design tokens
    --epg-panel-bg: var(--app-widget-bg);
    --epg-header-bg: var(--app-widget-header-bg);
    --epg-header-border: var(--app-widget-header-border);
    --epg-shadow: var(--app-widget-shadow);
    --epg-text-primary: var(--app-heading-color);
    --epg-text-secondary: var(--app-body-color);
    --epg-text-tertiary: var(--app-muted-color);
    --epg-accent: var(--app-selection-color);
    --epg-panel-border: color-mix(
        in srgb,
        var(--app-selection-color) 15%,
        transparent
    );
    --epg-panel-border-glow: color-mix(
        in srgb,
        var(--app-selection-color) 25%,
        transparent
    );
    --epg-accent-glow: color-mix(
        in srgb,
        var(--app-selection-color) 40%,
        transparent
    );
    --epg-item-border: var(--app-separator);
    --epg-item-hover: var(--app-hover-overlay);
    --epg-progress-track: color-mix(
        in srgb,
        var(--app-on-surface) 8%,
        transparent
    );
    --epg-icon-bg: color-mix(
        in srgb,
        var(--app-selection-color) 12%,
        transparent
    );
    --epg-scrollbar-thumb: color-mix(
        in srgb,
        var(--app-selection-color) 30%,
        transparent
    );
    --epg-scrollbar-track: color-mix(
        in srgb,
        var(--app-on-surface) 5%,
        transparent
    );

    // Status colors — semantic, not theme-dependent
    --epg-success: #22c55e;
    --epg-success-glow: rgba(34, 197, 94, 0.3);
    --epg-error: #ef4444;
    --epg-error-glow: rgba(239, 68, 68, 0.3);
    --epg-queued: #a78bfa;
    --epg-queued-glow: rgba(167, 139, 250, 0.3);
    --epg-queue-bg: color-mix(in srgb, var(--epg-queued) 6%, transparent);
    --epg-queue-border: color-mix(in srgb, var(--epg-queued) 15%, transparent);
}

.epg-progress-panel {
    position: fixed;
    bottom: 20px;
    left: 76px;
    width: 340px;
    max-width: calc(100vw - 96px);
    background: var(--epg-panel-bg);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-radius: 16px;
    box-shadow: var(--epg-shadow);
    z-index: 900;
    overflow: hidden;
    border: 1px solid var(--epg-panel-border);

    &::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        height: 1px;
        background: linear-gradient(
            90deg,
            transparent 0%,
            var(--epg-panel-border-glow) 20%,
            var(--epg-accent-glow) 50%,
            var(--epg-panel-border-glow) 80%,
            transparent 100%
        );
    }

    animation: slideInFromLeft 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideInFromLeft {
    from {
        opacity: 0;
        transform: translateX(-24px) scale(0.96);
    }

    to {
        opacity: 1;
        transform: translateX(0) scale(1);
    }
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    background: var(--epg-header-bg);
    border-bottom: 1px solid var(--epg-header-border);
    position: relative;

    .header-title {
        display: flex;
        align-items: center;
        gap: 10px;
        font-weight: 600;
        font-size: 13px;
        letter-spacing: 0.02em;
        color: var(--epg-text-primary);
        text-transform: uppercase;

        mat-icon {
            font-size: 20px;
            width: 20px;
            height: 20px;
            color: var(--epg-accent);
            filter: drop-shadow(0 0 6px var(--epg-accent-glow));
            animation: pulse-glow 2s ease-in-out infinite;
        }

        .minimized-summary {
            font-size: 12px;
            font-weight: 500;
            text-transform: none;
            letter-spacing: normal;
            color: var(--epg-text-secondary);
        }
    }

    .header-actions {
        display: flex;
        align-items: center;
        gap: 2px;
    }

    .minimize-btn,
    .dismiss-all-btn {
        width: 28px;
        height: 28px;
        padding: 2px;
        line-height: 28px;
        border-radius: 8px;
        transition: all 0.2s ease;
        color: var(--epg-text-tertiary);

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
        }
    }
}

.epg-progress-panel--minimized {
    width: auto;
    min-width: 200px;
    max-width: 320px;

    .panel-header {
        border-bottom: none;
    }
}

@keyframes pulse-glow {
    0%,
    100% {
        filter: drop-shadow(0 0 4px var(--epg-accent-glow));
    }

    50% {
        filter: drop-shadow(0 0 10px var(--epg-accent-glow));
    }
}

.imports-list {
    max-height: 360px;
    overflow-y: auto;
    padding: 4px 0;

    &::-webkit-scrollbar {
        width: 6px;
    }

    &::-webkit-scrollbar-track {
        background: var(--epg-scrollbar-track);
        border-radius: 3px;
        margin: 4px 0;
    }

    &::-webkit-scrollbar-thumb {
        background: var(--epg-scrollbar-thumb);
        border-radius: 3px;

        &:hover {
            background: var(--epg-accent);
        }
    }
}

.import-item {
    padding: 6px 12px;
    border-radius: 10px;
    transition: all 0.2s ease;
    position: relative;
    margin: 0 6px;

    &:not(:last-child) {
        margin-bottom: 2px;
    }

    &:hover {
        background: var(--epg-item-hover);
    }

    .item-header {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 10px;

        .status-icon-wrapper {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 32px;
            height: 32px;
            border-radius: 8px;
            background: var(--epg-icon-bg);
            flex-shrink: 0;
        }

        mat-icon {
            font-size: 18px;
            width: 18px;
            height: 18px;
            transition: all 0.3s ease;
        }

        .item-url {
            flex: 1;
            font-size: 12px;
            font-weight: 500;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            color: var(--epg-text-secondary);
            font-family: 'SF Mono', 'Fira Code', 'Monaco', monospace;
            letter-spacing: -0.02em;
        }

        .dismiss-btn {
            width: 26px;
            height: 26px;
            padding: 2px;
            line-height: 26px;
            border-radius: 6px;
            opacity: 0;
            transition: all 0.2s ease;
            color: var(--epg-text-tertiary);

            mat-icon {
                font-size: 16px;
                width: 16px;
                height: 16px;
            }
        }
    }

    &:hover .dismiss-btn {
        opacity: 1;
    }

    &.status-loading {
        .status-icon-wrapper mat-icon {
            color: var(--epg-accent);
        }
    }

    &.status-complete {
        .status-icon-wrapper mat-icon {
            color: var(--epg-success);
            filter: drop-shadow(0 0 6px var(--epg-success-glow));
        }
    }

    &.status-error {
        .status-icon-wrapper mat-icon {
            color: var(--epg-error);
            filter: drop-shadow(0 0 6px var(--epg-error-glow));
        }
    }
}

.spinning {
    animation: spin 1.2s linear infinite;
}

@keyframes spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

.item-stats {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-left: 42px;
    min-height: 24px;

    .stat-badge {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        padding: 4px 8px;
        border-radius: 999px;
        font-size: 11px;
        font-weight: 500;
        background: var(--epg-item-border);
        color: var(--epg-text-secondary);

        mat-icon {
            font-size: 14px;
            width: 14px;
            height: 14px;
        }
    }

    .error-text {
        font-size: 12px;
        color: var(--epg-error);
    }
}

.queue-section {
    margin: 8px 6px 6px;
    padding: 10px 12px;
    border-radius: 12px;
    background: var(--epg-queue-bg);
    border: 1px solid var(--epg-queue-border);
}

.queue-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
    font-size: 12px;
    font-weight: 600;
    color: var(--epg-text-primary);

    mat-icon {
        font-size: 16px;
        width: 16px;
        height: 16px;
        color: var(--epg-queued);
    }
}

.queue-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.queue-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 6px 8px;
    border-radius: 8px;
    color: var(--epg-text-secondary);

    .queue-position {
        width: 18px;
        text-align: center;
        font-size: 11px;
        font-weight: 700;
        color: var(--epg-queued);
    }

    .queue-url {
        flex: 1;
        font-size: 12px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        font-family: 'SF Mono', 'Fira Code', 'Monaco', monospace;
    }

    .dismiss-btn {
        width: 24px;
        height: 24px;
        padding: 2px;
        line-height: 24px;
        color: var(--epg-text-tertiary);
    }
}

@media (max-width: 700px) {
    .epg-progress-panel {
        left: 76px;
        right: 12px;
        bottom: 12px;
        width: auto;
        max-width: none;
    }
}

@media (max-width: 640px) {
    .epg-progress-panel {
        left: 12px;
    }
}

